export const QUESTIONS = [
  // SECTION 1 — ANATOMY (1-25)
  { id: 1, section: 1, q: 'Which laryngeal muscle is innervated by the external branch of the superior laryngeal nerve?', options: ['Posterior cricoarytenoid', 'Lateral cricoarytenoid', 'Cricothyroid', 'Thyroarytenoid', 'Interarytenoid'], answer: 2, rationale: 'The external branch of the SLN supplies ONLY the cricothyroid muscle — the sole tensor of the vocal cords. All other intrinsic laryngeal muscles are innervated by the recurrent laryngeal nerve.' },
  { id: 2, section: 1, q: 'Bilateral injury to the recurrent laryngeal nerves immediately after thyroidectomy most likely results in:', options: ['Hoarseness without airway compromise', 'Stridor and airway obstruction from adducted cords', 'Aphonia with cords in cadaveric position', 'Loss of gag reflex with aspiration', 'Bilateral vocal cord paralysis in abduction'], answer: 1, rationale: 'Bilateral RLN injury results in unopposed cricothyroid action (the only muscle the RLN does NOT supply), pulling cords into adduction → stridor and airway obstruction.' },
  { id: 3, section: 1, q: 'The narrowest portion of the airway in a healthy 2-year-old child is at the level of the:', options: ['Glottis', 'Vocal cords', 'Cricoid cartilage', 'Carina', 'Epiglottis'], answer: 2, rationale: 'Until approximately age 8, the cricoid (subglottic) ring is the narrowest part of the pediatric airway. In adults, the glottis (vocal cords) is the narrowest point.' },
  { id: 4, section: 1, q: 'In an adult, the spinal cord normally terminates at which vertebral level?', options: ['T12', 'L1', 'L3', 'L5', 'S2'], answer: 1, rationale: 'The conus medullaris terminates at L1 in adults. Spinal anesthesia should be performed below L1 — L3-L4 or L4-L5 (Tuffier\'s line) is standard.' },
  { id: 5, section: 1, q: 'An epidural needle inserted via the midline approach traverses which ligament IMMEDIATELY before entering the epidural space?', options: ['Supraspinous ligament', 'Interspinous ligament', 'Ligamentum flavum', 'Posterior longitudinal ligament', 'Anterior longitudinal ligament'], answer: 2, rationale: 'Skin → subcutaneous → supraspinous → interspinous → ligamentum flavum → epidural space. Loss of resistance is felt as the needle passes through the ligamentum flavum.' },
  { id: 6, section: 1, q: 'An interscalene brachial plexus block consistently spares which nerve?', options: ['Musculocutaneous', 'Median', 'Radial', 'Ulnar', 'Axillary'], answer: 3, rationale: 'Interscalene blocks deposit local anesthetic at C5–C7 roots/upper trunks. The ulnar nerve (C8–T1, lower trunk) is frequently spared, making interscalene blocks inadequate for hand/forearm surgery.' },
  { id: 7, section: 1, q: 'Interscalene blockade reliably produces ipsilateral phrenic nerve paresis. The diaphragm receives its motor innervation from spinal segments:', options: ['C2-C3-C4', 'C3-C4-C5', 'C4-C5-C6', 'C5-C6-C7', 'T1-T2-T3'], answer: 1, rationale: '"C3, 4, 5 keep the diaphragm alive." Interscalene injection causes ~100% incidence of ipsilateral phrenic palsy and approximately 25–30% reduction in pulmonary function.' },
  { id: 8, section: 1, q: 'In a patient with right-dominant coronary circulation, the AV node is most commonly supplied by the:', options: ['Left anterior descending artery', 'Left circumflex artery', 'Right coronary artery', 'Left main coronary artery', 'Posterior descending artery directly from the aorta'], answer: 2, rationale: 'In approximately 85% of the population (right-dominant), the RCA gives rise to the posterior descending artery, which supplies the AV node in 80–90% of patients.' },
  { id: 9, section: 1, q: 'The most common perioperative peripheral nerve injury is to the:', options: ['Brachial plexus', 'Common peroneal nerve', 'Sciatic nerve', 'Ulnar nerve', 'Femoral nerve'], answer: 3, rationale: 'Ulnar neuropathy is the single most common perioperative peripheral nerve injury, accounting for approximately one-third of claims.' },
  { id: 10, section: 1, q: 'A patient in the lithotomy position develops foot drop and lateral leg numbness postoperatively. The most likely mechanism is compression of the:', options: ['Sciatic nerve at the buttock', 'Common peroneal nerve at the fibular head', 'Femoral nerve at the inguinal ligament', 'Lateral femoral cutaneous nerve', 'Tibial nerve at the popliteal fossa'], answer: 1, rationale: 'The common peroneal nerve wraps superficially around the head of the fibula, where it is vulnerable to compression against lithotomy stirrups. Injury produces foot drop and sensory loss over the lateral leg and dorsum of the foot.' },
  { id: 11, section: 1, q: 'A stellate ganglion block performed at the C6 transverse process produces all the following ipsilateral findings EXCEPT:', options: ['Ptosis', 'Miosis', 'Anhidrosis', 'Mydriasis', 'Enophthalmos'], answer: 3, rationale: 'Stellate ganglion block causes Horner\'s syndrome: ptosis, miosis (NOT mydriasis), anhidrosis, and enophthalmos. Mydriasis results from sympathetic stimulation, not blockade.' },
  { id: 12, section: 1, q: 'A patient receiving epidural anesthesia for cesarean delivery has lost sensation up to the level of the xiphoid process. The most cephalad dermatome blocked is approximately:', options: ['T4', 'T6', 'T8', 'T10', 'T12'], answer: 1, rationale: 'The xiphoid corresponds to T6-T7. Cesarean delivery requires a block to at least T4 (nipple line) — a T6 block is inadequate for peritoneal traction.' },
  { id: 13, section: 1, q: 'The cricothyroid membrane is bordered superiorly by the thyroid cartilage and inferiorly by the cricoid cartilage. The safest puncture site for emergency cricothyrotomy is the:', options: ['Upper third of the membrane in the midline', 'Middle third laterally', 'Lower third in the midline', 'Junction with the thyroid cartilage', 'Posterior aspect of the cricoid'], answer: 2, rationale: 'The cricothyroid arteries cross the upper third of the membrane. Puncture is safest in the lower one-third in the midline to avoid these vessels.' },
  { id: 14, section: 1, q: 'Which nerve must be blocked (in addition to others) to abolish the gag reflex for awake oral fiberoptic intubation?', options: ['Trigeminal nerve (V3)', 'Glossopharyngeal nerve (CN IX)', 'Vagus nerve (CN X) only', 'Hypoglossal nerve (CN XII)', 'Facial nerve (CN VII)'], answer: 1, rationale: 'The afferent limb of the gag reflex is mediated by CN IX, which provides sensation to the posterior tongue, vallecula, anterior epiglottis, and oropharynx.' },
  { id: 15, section: 1, q: 'In a supine adult patient, the LOWEST point of the thoracic spine on the AP plane is at which vertebral level?', options: ['T2', 'T5', 'T8', 'T10', 'T12'], answer: 1, rationale: 'Thoracic kyphosis reaches its lowest point at T5-T6 in the supine position. Hyperbaric spinal LA spreads cephalad until it pools at this level.' },
  { id: 16, section: 1, q: 'An adductor canal (saphenous nerve) block is preferred over a femoral nerve block for knee surgery analgesia because:', options: ['It provides better motor block', 'It blocks the obturator nerve more reliably', 'It preserves quadriceps strength', 'It has lower local anesthetic systemic toxicity risk', 'It covers a larger sensory distribution'], answer: 2, rationale: 'The adductor canal block targets the saphenous nerve (sensory branch of femoral), sparing the motor branches to the quadriceps — allowing earlier ambulation and reducing fall risk.' },
  { id: 17, section: 1, q: 'Tuffier\'s line (the intercristal line connecting the iliac crests) corresponds to which vertebral level?', options: ['L2-L3', 'L3-L4', 'L4 or L4-L5', 'L5-S1', 'S1-S2'], answer: 2, rationale: 'Tuffier\'s line typically crosses L4 or the L4-L5 interspace — well below the conus medullaris (L1) and the standard landmark for spinal anesthesia.' },
  { id: 18, section: 1, q: 'The SA node receives its arterial supply from the right coronary artery in approximately what percentage of patients?', options: ['20%', '40%', '60%', '80%', '100%'], answer: 2, rationale: 'The SA node is supplied by the RCA in approximately 60% of patients and by the left circumflex in the remaining 40%.' },
  { id: 19, section: 1, q: 'Which of the following nerves is NOT covered by a standard ankle block consisting of 5 injections?', options: ['Tibial nerve', 'Deep peroneal nerve', 'Saphenous nerve', 'Sural nerve', 'Obturator nerve'], answer: 4, rationale: 'The 5-nerve ankle block covers: deep peroneal, superficial peroneal, tibial, sural, and saphenous nerves. The obturator nerve does not extend to the ankle.' },
  { id: 20, section: 1, q: 'Which of the following regional anesthesia procedures carries the HIGHEST risk of pneumothorax?', options: ['Interscalene block', 'Supraclavicular block', 'Axillary block', 'Infraclavicular block', 'Femoral block'], answer: 1, rationale: 'Supraclavicular block carries the highest pneumothorax risk because the pleura lies just deep to the first rib and the brachial plexus trunks.' },
  { id: 21, section: 1, q: 'An endotracheal tube inadvertently advanced too deeply is most likely to enter the right mainstem bronchus because it is:', options: ['Wider and more vertical than the left', 'Shorter and more horizontal than the left', 'More posterior than the left', 'Closer to the vocal cords', 'More easily compressed by the heart'], answer: 0, rationale: 'The right mainstem bronchus is shorter, wider, and more vertical (≈25° from midline) than the left (≈45°).' },
  { id: 22, section: 1, q: 'The inferior vena cava passes through the diaphragm at which vertebral level?', options: ['T6', 'T8', 'T10', 'T12', 'L1'], answer: 1, rationale: 'Diaphragmatic openings: T8 — caval hiatus (IVC); T10 — esophageal hiatus; T12 — aortic hiatus. Mnemonic: "I 8 (T8) 10 (T10) EGGs AT (T12) 12."' },
  { id: 23, section: 1, q: 'Compared to adults, the pediatric airway differs in all the following ways EXCEPT:', options: ['The larynx is more cephalad', 'The epiglottis is longer and more floppy', 'The vocal cords are angled anteriorly', 'The cricoid is the narrowest portion', 'The tongue is relatively smaller'], answer: 4, rationale: 'The pediatric tongue is RELATIVELY LARGER in proportion to the oral cavity, not smaller.' },
  { id: 24, section: 1, q: 'Which structures make up the brachial plexus in correct anatomical order from proximal to distal?', options: ['Cords, trunks, divisions, branches, roots', 'Roots, trunks, divisions, cords, branches', 'Roots, divisions, trunks, cords, branches', 'Trunks, roots, divisions, cords, branches', 'Roots, trunks, cords, divisions, branches'], answer: 1, rationale: '"Robert Taylor Drinks Cold Beer": Roots → Trunks → Divisions → Cords → Branches.' },
  { id: 25, section: 1, q: 'The most common site of anterior epistaxis is:', options: ['Sphenopalatine artery', 'Kiesselbach plexus', 'Posterior ethmoidal artery', 'Internal carotid artery', 'Maxillary artery'], answer: 1, rationale: 'Kiesselbach plexus (Little\'s area) on the anterior nasal septum is the most common site of epistaxis, accounting for ~90% of nosebleeds.' },

  // SECTION 2 — PHYSIOLOGY (26-50)
  { id: 26, section: 2, q: 'Cardiac output equals heart rate multiplied by stroke volume. Which of the following PRIMARILY determines stroke volume?', options: ['Preload only', 'Afterload only', 'Contractility only', 'Preload, afterload, and contractility', 'Heart rate'], answer: 3, rationale: 'Stroke volume is determined by three factors: preload (Frank-Starling), afterload (SVR), and contractility (ESPVR slope/EF).' },
  { id: 27, section: 2, q: 'Coronary perfusion pressure to the left ventricle is best calculated as:', options: ['MAP – CVP', 'MAP – LVEDP', 'Aortic diastolic pressure – LVEDP', 'Systolic BP – diastolic BP', 'Diastolic BP – PCWP'], answer: 2, rationale: 'LV coronary blood flow occurs almost exclusively during diastole. CPP = aortic diastolic pressure – LVEDP.' },
  { id: 28, section: 2, q: 'Functional residual capacity (FRC) consists of:', options: ['Tidal volume + inspiratory reserve volume', 'Inspiratory reserve volume + expiratory reserve volume', 'Expiratory reserve volume + residual volume', 'Tidal volume + residual volume', 'Vital capacity − tidal volume'], answer: 2, rationale: 'FRC = ERV + RV = volume in the lungs at end-expiration during quiet breathing (~2400 mL in a 70-kg adult).' },
  { id: 29, section: 2, q: 'Which factor causes a RIGHTWARD shift of the oxyhemoglobin dissociation curve?', options: ['Hypothermia', 'Alkalosis', 'Decreased 2,3-DPG', 'Hyperthermia', 'Carbon monoxide'], answer: 3, rationale: 'Right shift (↓ Hb-O₂ affinity): ↑ temperature, ↑ PaCO₂, ↓ pH (acidosis), ↑ 2,3-DPG. Left shift: hypothermia, alkalosis, ↓ 2,3-DPG, fetal Hb, COHb.' },
  { id: 30, section: 2, q: 'A patient with carbon monoxide poisoning has SpO₂ 99% on the pulse oximeter. The true SaO₂ measured by co-oximetry is 70%. The pulse oximeter reads falsely high because:', options: ['Pulse oximetry detects only methemoglobin', 'HbCO and HbO₂ absorb light similarly at 660 nm', 'CO poisoning causes hyperthermia', 'Pulse oximetry overestimates in anemia', 'Dark skin pigmentation interferes with the reading'], answer: 1, rationale: 'Standard pulse oximeters use 660 nm and 940 nm wavelengths. COHb absorbs similarly to HbO₂ at 660 nm → falsely HIGH SpO₂. Co-oximetry is required for accurate measurement.' },
  { id: 31, section: 2, q: 'Which is true regarding cerebral blood flow and CO₂?', options: ['CBF is independent of PaCO₂', 'CBF doubles for every 10 mmHg rise in PaCO₂ over the range 20-80', 'CBF changes approximately 1-2 mL/100 g/min per mmHg change in PaCO₂', 'Hyperventilation to PaCO₂ 20 maintains its CBF-lowering effect for days', 'PaCO₂ effect on CBF is greater than the effect of PaO₂'], answer: 2, rationale: 'CBF changes ~1-2 mL/100 g/min per mmHg PaCO₂ over the range 20-80 mmHg. Hyperventilation effect attenuates over 6-12 hours as CSF bicarbonate equilibrates.' },
  { id: 32, section: 2, q: 'Which segment of the nephron is the target of loop diuretics?', options: ['Proximal convoluted tubule', 'Descending limb of the loop of Henle', 'Thick ascending limb of the loop of Henle', 'Distal convoluted tubule', 'Collecting duct'], answer: 2, rationale: 'Furosemide and loop diuretics block the Na-K-2Cl cotransporter in the thick ascending limb, where ~25% of filtered Na is normally reabsorbed.' },
  { id: 33, section: 2, q: 'A patient with a Na⁺ of 140, Cl⁻ of 100, and HCO₃⁻ of 10 has a pH of 7.20 and PaCO₂ of 25. The acid-base disorder is:', options: ['Anion gap metabolic acidosis with adequate respiratory compensation', 'Anion gap metabolic acidosis with inadequate respiratory compensation', 'Non-anion gap metabolic acidosis', 'Respiratory acidosis with metabolic compensation', 'Mixed respiratory and metabolic acidosis'], answer: 0, rationale: 'AG = 140-(100+10) = 30 (elevated). Winter\'s formula: expected PaCO₂ = 1.5(10) + 8 ± 2 = 21-25. Measured 25 = within range → adequate compensation.' },
  { id: 34, section: 2, q: 'Which factor is NOT synthesized by the liver?', options: ['Factor II (prothrombin)', 'Factor VII', 'Factor IX', 'Factor VIII', 'Fibrinogen'], answer: 3, rationale: 'The liver synthesizes ALL coagulation factors EXCEPT Factor VIII (synthesized by vascular endothelial cells) and von Willebrand factor.' },
  { id: 35, section: 2, q: 'A drug with a hepatic extraction ratio of 0.9 will have its clearance MOST affected by:', options: ['Changes in plasma protein binding', 'Changes in intrinsic hepatic enzyme activity', 'Changes in hepatic blood flow', 'Changes in renal clearance', 'Changes in volume of distribution'], answer: 2, rationale: 'High-extraction drugs (ER >0.7) are "flow-limited" — clearance depends on hepatic blood flow. Examples: propofol, fentanyl, morphine, lidocaine, propranolol.' },
  { id: 36, section: 2, q: 'The Monro-Kellie doctrine states that the cranial vault contains three components in fixed total volume. These are:', options: ['Brain, blood, fat', 'Brain, CSF, lymph', 'Brain, blood, CSF', 'Brain, ventricular fluid, blood', 'Brain, gray matter, white matter'], answer: 2, rationale: 'The Monro-Kellie doctrine: the rigid cranium holds brain parenchyma (~80%), blood (~12%), and CSF (~8%). Any increase in one must be offset by a decrease in another.' },
  { id: 37, section: 2, q: 'Which technique most effectively blunts the neuroendocrine stress response to surgery?', options: ['Volatile anesthesia alone (sevoflurane 1 MAC)', 'TIVA with propofol', 'High-dose opioid technique or regional anesthesia', 'Light anesthesia plus neuromuscular blockade', 'Nitrous oxide 70%'], answer: 2, rationale: 'High-dose opioid and especially regional anesthesia (epidural, spinal) blunt the cortisol surge, catecholamine release, and hyperglycemia of surgery. Volatile anesthesia alone does NOT effectively block the stress response.' },
  { id: 38, section: 2, q: 'Preoperative α-adrenergic blockade is required before β-blockade in a patient with pheochromocytoma because:', options: ['β-blockers alone cause severe bradycardia', 'β-blockers exacerbate insulin resistance', 'Unopposed α-stimulation can precipitate hypertensive crisis', 'α-blockers reduce CV mortality independently', 'β-blockers cross the blood-brain barrier and worsen anxiety'], answer: 2, rationale: 'β-blockade in a patient with circulating catecholamines blocks β2-mediated vasodilation, leaving unopposed α1 vasoconstriction → severe hypertensive crisis.' },
  { id: 39, section: 2, q: 'In the upright, spontaneously breathing patient, V/Q matching at the apex of the lung is:', options: ['V/Q < 1 (shunt-like)', 'V/Q = 1 (ideal)', 'V/Q > 1 (dead-space-like)', 'Equal to V/Q at the base', 'Unable to be calculated'], answer: 2, rationale: 'In the upright lung, perfusion increases more than ventilation from apex to base. At the apex, V > Q (V/Q > 1, dead-space-like); at the base, Q > V (V/Q < 1, shunt-like).' },
  { id: 40, section: 2, q: 'Which maternal physiologic change is correctly described at term?', options: ['Cardiac output decreases by 20%', 'Functional residual capacity increases', 'Minute ventilation increases by 50%', 'Plasma volume decreases', 'Gastric emptying accelerates'], answer: 2, rationale: 'At term: CO increases ~40-50%, FRC decreases ~20%, minute ventilation increases ~50% (driven by tidal volume), plasma volume increases ~50%, gastric emptying SLOWS after labor begins.' },
  { id: 41, section: 2, q: 'On a pressure-volume loop, the slope of the end-systolic pressure-volume relationship (ESPVR) reflects:', options: ['Preload', 'Afterload', 'Contractility', 'Heart rate', 'Stroke work'], answer: 2, rationale: 'The ESPVR is the line connecting end-systolic points at varying preloads. Its slope is a LOAD-INDEPENDENT measure of contractility.' },
  { id: 42, section: 2, q: 'Renal autoregulation maintains a relatively constant glomerular filtration rate over what range of mean arterial pressures?', options: ['40-80 mmHg', '60-160 mmHg', '80-200 mmHg', '100-180 mmHg', 'No autoregulation occurs'], answer: 1, rationale: 'Renal autoregulation maintains GFR over MAP 60-160 mmHg via the myogenic response and tubuloglomerular feedback. Below 60 mmHg, GFR falls linearly.' },
  { id: 43, section: 2, q: 'The PRIMARY drive to ventilation in healthy individuals comes from:', options: ['Peripheral chemoreceptors responding to PaO₂', 'Central chemoreceptors responding to CSF [H⁺]', 'Carotid body responding to pH', 'Lung stretch receptors', 'Voluntary cortical control'], answer: 1, rationale: 'Central chemoreceptors in the ventral medulla respond to CSF [H⁺] (reflecting PaCO₂) — this is the primary drive to ventilation in healthy individuals.' },
  { id: 44, section: 2, q: 'A patient with traumatic brain injury has MAP 90, ICP 25. Cerebral perfusion pressure (CPP) is:', options: ['65 mmHg', '75 mmHg', '90 mmHg', '115 mmHg', 'Cannot be calculated'], answer: 0, rationale: 'CPP = MAP − ICP = 90 − 25 = 65 mmHg. Target CPP in TBI is 60-70 mmHg.' },
  { id: 45, section: 2, q: 'Hypoxic pulmonary vasoconstriction (HPV):', options: ['Worsens V/Q mismatch', 'Is potentiated by all volatile anesthetics', 'Diverts blood from poorly ventilated to better ventilated alveoli', 'Is the primary mechanism of pulmonary hypertension in scuba divers', 'Is inhibited by inhaled nitric oxide'], answer: 2, rationale: 'HPV: alveolar hypoxia → local pulmonary vasoconstriction → blood redirected to better-ventilated alveoli → IMPROVES V/Q matching. All volatile anesthetics INHIBIT HPV dose-dependently.' },
  { id: 46, section: 2, q: 'The P50 of normal adult hemoglobin is:', options: ['13.3 mmHg', '20 mmHg', '26.6 mmHg', '40 mmHg', '60 mmHg'], answer: 2, rationale: 'P50 = PaO₂ at which Hb is 50% saturated = 26.6 mmHg in normal adult Hb. Fetal Hb has lower P50 (~19 mmHg), facilitating O₂ transfer across the placenta.' },
  { id: 47, section: 2, q: 'The Bainbridge reflex describes:', options: ['Vasoconstriction in response to hypotension', 'Tachycardia in response to atrial stretch', 'Bradycardia in response to increased ICP', 'Coughing during laryngoscopy', 'Hypertension after extubation'], answer: 1, rationale: 'The Bainbridge reflex: stretch receptors in the right atrium → afferent vagal fibers → ↑ heart rate. Activated by rapid IV fluid bolus or increased venous return.' },
  { id: 48, section: 2, q: 'Closing capacity (CC) is:', options: ['The same as functional residual capacity', 'The lung volume at which small airways begin to close', 'Increased by deep breathing', 'Decreased with age', 'Equal to vital capacity minus inspiratory capacity'], answer: 1, rationale: 'Closing capacity = volume at which small airways begin to close. CC increases with age; when CC > FRC, airways close during tidal breathing → atelectasis and shunt.' },
  { id: 49, section: 2, q: 'A 70-kg patient has an estimated total blood volume of approximately:', options: ['3.0 L', '3.5 L', '5.0 L', '7.0 L', '10 L'], answer: 2, rationale: 'Adult blood volume ≈ 70 mL/kg (men). A 70-kg adult ≈ 5 L.' },
  { id: 50, section: 2, q: 'Dead space ventilation is increased by all of the following EXCEPT:', options: ['Pulmonary embolism', 'Hypotension/low cardiac output', 'Excessive PEEP', 'Hypoventilation with hypercapnia', 'Aging lung'], answer: 3, rationale: 'HYPOVENTILATION causes hypercapnia by reducing minute ventilation overall, NOT by increasing dead space. PE, low CO, high PEEP, and aging all increase dead space.' },

  // SECTION 3 — PHARMACOLOGY (51-100)
  { id: 51, section: 3, q: 'Which IV induction agent is most likely to cause pain on injection and myoclonus, while preserving cardiovascular stability and adrenocortical function?', options: ['Propofol', 'Etomidate', 'Ketamine', 'Methohexital', 'Midazolam'], answer: 1, rationale: 'Etomidate causes pain on injection (~50%), myoclonus (~50%), and reversible adrenocortical suppression. It is hemodynamically the most stable induction agent.' },
  { id: 52, section: 3, q: 'Propofol\'s mechanism of action is best described as:', options: ['NMDA receptor antagonism', 'GABA-A receptor potentiation', 'Opioid mu receptor agonism', 'Alpha-2 receptor agonism', 'Glycine receptor antagonism'], answer: 1, rationale: 'Propofol potentiates GABA-A receptor activity, increasing chloride conductance and producing hyperpolarization.' },
  { id: 53, section: 3, q: 'Ketamine\'s bronchodilation and sympathomimetic effects make it especially useful in which scenario?', options: ['Hypertensive crisis', 'Severe asthma exacerbation requiring intubation', 'Open-globe injury', 'Closed head injury with elevated ICP', 'Pulmonary hypertension'], answer: 1, rationale: 'Ketamine produces bronchodilation and centrally-mediated sympathetic stimulation — ideal in status asthmaticus and hypovolemic shock.' },
  { id: 54, section: 3, q: 'Which volatile anesthetic has the LOWEST blood:gas partition coefficient, allowing the fastest induction and emergence?', options: ['Halothane', 'Isoflurane', 'Sevoflurane', 'Desflurane', 'Nitrous oxide'], answer: 4, rationale: 'N₂O 0.47 < Des 0.42 (N₂O fastest overall). Among potent volatiles, desflurane has the lowest blood:gas (0.42). Nitrous oxide has the fastest kinetics but limited potency.' },
  { id: 55, section: 3, q: 'The MAC of isoflurane in a healthy adult is approximately:', options: ['0.75%', '1.2%', '1.85%', '2.5%', '6.0%'], answer: 1, rationale: 'Standard MAC: Halothane 0.75%, Isoflurane 1.15-1.20%, Sevoflurane 1.85-2.0%, Desflurane 6.0%, N₂O 104%.' },
  { id: 56, section: 3, q: 'Compound A is a degradation product associated with which volatile and which CO₂ absorbent?', options: ['Desflurane with desiccated soda lime', 'Sevoflurane with desiccated soda lime/baralyme', 'Isoflurane with calcium hydroxide', 'Halothane with soda lime', 'Enflurane with baralyme'], answer: 1, rationale: 'Sevoflurane reacts with strong bases (KOH, NaOH) in dry CO₂ absorbents to produce Compound A — nephrotoxic in rats. Use absorbents low in strong bases and avoid low flows (<1 L/min) for prolonged cases.' },
  { id: 57, section: 3, q: 'Which volatile anesthetic is most likely to cause coronary steal in patients with coronary artery disease?', options: ['Halothane', 'Isoflurane', 'Sevoflurane', 'Desflurane', 'None of these clinically'], answer: 4, rationale: 'Historical concern with isoflurane (most potent coronary vasodilator) was "coronary steal." Modern data show no clinically significant difference between modern volatiles in well-monitored patients.' },
  { id: 58, section: 3, q: 'Which opioid has the fastest onset and shortest context-sensitive half-time, making it ideal for short procedures?', options: ['Morphine', 'Fentanyl', 'Sufentanil', 'Alfentanil', 'Remifentanil'], answer: 4, rationale: 'Remifentanil is hydrolyzed by nonspecific plasma/tissue esterases with a context-sensitive half-time of ~3-5 min regardless of infusion duration — uniquely flat.' },
  { id: 59, section: 3, q: 'Morphine\'s active metabolite that contributes to prolonged effect in renal failure is:', options: ['Morphine-3-glucuronide', 'Morphine-6-glucuronide', 'Normorphine', 'Norpethidine', 'Hydromorphone-3-glucuronide'], answer: 1, rationale: 'Morphine-6-glucuronide is an active μ-agonist that accumulates in renal failure, prolonging respiratory depression. Prefer hydromorphone or fentanyl in CKD.' },
  { id: 60, section: 3, q: 'A patient develops chest wall rigidity 90 seconds after a rapid 5-mcg/kg IV bolus of fentanyl. The most appropriate immediate management is:', options: ['Naloxone 0.4 mg IV', 'Succinylcholine and mask ventilation', 'Reverse Trendelenburg and 100% O₂', 'Flumazenil 0.2 mg IV', 'Observation only'], answer: 1, rationale: 'Opioid-induced chest wall rigidity — mask ventilation is often impossible. Treatment: paralyze with succinylcholine (or NDMR) and ventilate. Prevent by slower administration.' },
  { id: 61, section: 3, q: 'Succinylcholine is contraindicated in all of the following EXCEPT:', options: ['48 hours after a major burn', 'Acute spinal cord injury at 1 week', 'Hypokalemia of 3.1 mEq/L', 'Severe muscular dystrophy', 'History of malignant hyperthermia'], answer: 2, rationale: 'Succinylcholine causes a ~0.5 mEq/L K⁺ rise. Hypokalemia per se is NOT a contraindication. Burns >24h, SCI, muscular dystrophies, and MH history are contraindications.' },
  { id: 62, section: 3, q: 'Which feature distinguishes a phase II block from a phase I depolarizing block from succinylcholine?', options: ['Fade with TOF and post-tetanic potentiation', 'Sustained tetanus', 'TOF ratio > 0.9', 'No fade with TOF', 'Reversible by neostigmine without fade'], answer: 0, rationale: 'Phase II block: fade with TOF/tetanus, post-tetanic potentiation — resembles a nondepolarizing block. Phase I: no fade, no post-tetanic potentiation.' },
  { id: 63, section: 3, q: 'Which nondepolarizing muscle relaxant undergoes spontaneous Hofmann elimination and is preferred in renal or hepatic failure?', options: ['Vecuronium', 'Rocuronium', 'Pancuronium', 'Cisatracurium', 'Atracurium'], answer: 3, rationale: 'Cisatracurium undergoes organ-independent Hofmann elimination (pH/temperature-dependent) — ideal in renal/hepatic failure with no accumulation of active metabolites.' },
  { id: 64, section: 3, q: 'Sugammadex acts by:', options: ['Inhibiting acetylcholinesterase', 'Encapsulating steroidal NMBs (rocuronium, vecuronium) in a 1:1 complex', 'Antagonizing muscarinic receptors', 'Reversing benzylisoquinolinium agents', 'Stimulating presynaptic acetylcholine release'], answer: 1, rationale: 'Sugammadex is a modified γ-cyclodextrin that encapsulates rocuronium (and vecuronium) in a 1:1 inclusion complex. Dose: 2 mg/kg moderate block, 4 mg/kg deep block, 16 mg/kg immediate reversal.' },
  { id: 65, section: 3, q: 'Neostigmine reversal of a nondepolarizing block requires concurrent administration of glycopyrrolate primarily to:', options: ['Enhance neostigmine\'s effect at the NMJ', 'Antagonize neostigmine\'s muscarinic side effects (bradycardia, secretions)', 'Prevent recurarization', 'Accelerate metabolism of the NMB', 'Reduce postoperative nausea'], answer: 1, rationale: 'Neostigmine inhibits acetylcholinesterase → increased ACh at muscarinic receptors → bradycardia, bronchospasm, secretions. Glycopyrrolate blocks these muscarinic effects without crossing the BBB.' },
  { id: 66, section: 3, q: 'The most cardiotoxic local anesthetic in clinical use is:', options: ['Lidocaine', 'Mepivacaine', 'Ropivacaine', 'Bupivacaine', 'Chloroprocaine'], answer: 3, rationale: 'Bupivacaine has high lipid solubility and strong sodium-channel binding (slow dissociation — "fast in, slow out"). Cardiac arrest is often refractory; treat with lipid emulsion 20%.' },
  { id: 67, section: 3, q: 'The maximum recommended dose of plain lidocaine for infiltration in an adult is approximately:', options: ['3 mg/kg', '4.5 mg/kg', '7 mg/kg with epinephrine', '10 mg/kg', 'Both B and C'], answer: 4, rationale: 'Lidocaine: 4.5 mg/kg plain, 7 mg/kg with epinephrine. Both B (plain) and C (with epinephrine) represent correct maximum doses for different formulations.' },
  { id: 68, section: 3, q: 'True allergy to ester local anesthetics is most often due to:', options: ['The amide linkage', 'PABA metabolite', 'Sodium metabisulfite preservative', 'Methylparaben preservative', 'The benzene ring'], answer: 1, rationale: 'Esters (procaine, chloroprocaine, tetracaine, benzocaine) are metabolized to PABA (para-aminobenzoic acid), the immunogenic compound responsible for true allergy.' },
  { id: 69, section: 3, q: 'Benzocaine spray for topical airway anesthesia is associated with which serious adverse effect?', options: ['Methemoglobinemia', 'Anaphylaxis', 'Bronchospasm', 'Seizures', 'Hepatotoxicity'], answer: 0, rationale: 'Benzocaine and prilocaine can cause methemoglobinemia. Treatment: methylene blue 1-2 mg/kg IV. Pulse oximetry reads ~85% regardless of true SpO₂; co-oximetry required.' },
  { id: 70, section: 3, q: 'Initial management of local anesthetic systemic toxicity (LAST) cardiac arrest after bupivacaine includes all EXCEPT:', options: ['100% oxygen and airway management', '20% lipid emulsion 1.5 mL/kg bolus then 0.25 mL/kg/min infusion', 'Benzodiazepines for seizures', 'Vasopressin 40 units IV', 'Reduced epinephrine doses (<1 mcg/kg)'], answer: 3, rationale: 'ASRA LAST protocol: AVOID vasopressin (worsens outcomes). Use lipid emulsion, reduced epi doses (<1 mcg/kg), benzodiazepines for seizures, 100% O₂.' },
  { id: 71, section: 3, q: 'Neuraxial anesthesia is contraindicated within what interval after the last therapeutic enoxaparin (1 mg/kg q12h) dose?', options: ['6 hours', '12 hours', '24 hours', '48 hours', '72 hours'], answer: 2, rationale: 'ASRA: Prophylactic LMWH — wait 12 h. Therapeutic LMWH (1 mg/kg q12h) — wait 24 h. DOACs (apixaban, rivaroxaban) — 72 h.' },
  { id: 72, section: 3, q: 'Which vasopressor is the preferred first-line agent for spinal-induced hypotension in a healthy parturient?', options: ['Ephedrine', 'Phenylephrine', 'Norepinephrine', 'Epinephrine', 'Vasopressin'], answer: 1, rationale: 'Modern obstetric anesthesia recommends phenylephrine (pure α-1 agonist) as first-line — better fetal acid-base status than ephedrine, which causes fetal metabolic acidosis.' },
  { id: 73, section: 3, q: 'Phenylephrine\'s primary mechanism of action and main reflex effect are:', options: ['β1 agonist; reflex tachycardia', 'α1 agonist; reflex bradycardia', 'β2 agonist; reflex tachycardia', 'Mixed α/β; no reflex change', 'α2 agonist; sedation'], answer: 1, rationale: 'Phenylephrine is a pure α1 agonist → arterial vasoconstriction → ↑SVR → ↑BP → baroreflex-mediated bradycardia.' },
  { id: 74, section: 3, q: 'Which beta-blocker has the shortest elimination half-life (~9 min) due to metabolism by red blood cell esterases?', options: ['Propranolol', 'Metoprolol', 'Esmolol', 'Labetalol', 'Atenolol'], answer: 2, rationale: 'Esmolol is a cardioselective β1 blocker metabolized by RBC esterases (not pseudocholinesterase), giving a half-life of ~9 minutes — ideal for titratable intraoperative HR/BP control.' },
  { id: 75, section: 3, q: 'Which antiemetic prolongs the QT interval and carries an FDA boxed warning?', options: ['Ondansetron', 'Metoclopramide', 'Droperidol', 'Dexamethasone', 'Both A and C'], answer: 4, rationale: 'Both ondansetron (5-HT3 antagonist) and droperidol (D2 antagonist) prolong QT and risk torsades — both carry FDA warnings.' },
  { id: 76, section: 3, q: 'Flumazenil\'s primary risks include all EXCEPT:', options: ['Withdrawal seizures in chronic benzodiazepine users', 'Re-sedation due to short half-life (~1 hour)', 'Resedation requiring repeat dosing', 'Reversal of analgesia', 'Precipitation of seizures in patients on TCAs or with epilepsy'], answer: 3, rationale: 'Flumazenil is a competitive GABA-A benzodiazepine receptor antagonist. It does NOT affect opioid analgesia — opioids act at μ receptors, not GABA.' },
  { id: 77, section: 3, q: 'Dexmedetomidine\'s principal site of action producing sedation is:', options: ['GABA-A receptors in the cortex', 'α2 receptors in the locus coeruleus', 'Imidazoline receptors in the medulla', 'Mu opioid receptors in the brainstem', 'NMDA receptors in the thalamus'], answer: 1, rationale: 'Dexmedetomidine is a highly selective α2 agonist (1600:1 vs α1) acting on the locus coeruleus → arousable, NREM-like sedation without significant respiratory depression.' },
  { id: 78, section: 3, q: 'A patient receives succinylcholine and remains paralyzed for 4 hours. Dibucaine number is 22. This indicates:', options: ['Normal pseudocholinesterase activity', 'Heterozygous atypical pseudocholinesterase', 'Homozygous atypical pseudocholinesterase', 'Acquired pseudocholinesterase deficiency', 'Myasthenia gravis'], answer: 2, rationale: 'Dibucaine number: ~80 = normal homozygous (2-3 min block); ~60 = heterozygous (20-30 min); ~20 = homozygous atypical (4-8 hours prolonged).' },
  { id: 79, section: 3, q: 'Vancomycin infused too rapidly classically causes:', options: ['Stevens-Johnson syndrome', 'Red man syndrome from histamine release', 'Anaphylaxis (IgE-mediated)', 'Disulfiram-like reaction', 'Nephrogenic diabetes insipidus'], answer: 1, rationale: 'Red man (red person) syndrome — flushing, pruritus, hypotension from non-immune histamine release. Prevent by infusing over 60+ minutes. Not a true allergy.' },
  { id: 80, section: 3, q: 'Mannitol\'s mechanism in reducing intracranial pressure is:', options: ['Loop of Henle sodium-potassium-chloride blockade', 'Aldosterone antagonism', 'Osmotic diuresis and reduction of cerebral water content', 'Carbonic anhydrase inhibition', 'ADH antagonism'], answer: 2, rationale: 'Mannitol (0.25-1 g/kg) is filtered but not reabsorbed → osmotic gradient pulls water out of brain into the vascular space, reducing ICP and cerebral water content.' },
  { id: 81, section: 3, q: 'A patient on chronic prednisone 20 mg/day undergoing major surgery should receive stress-dose steroids approximately equivalent to:', options: ['100 mg hydrocortisone before induction only', 'Hydrocortisone 100 mg q8h for 24-48 hours then taper', 'Continue daily dose without supplementation', 'Dexamethasone 4 mg once', 'Methylprednisolone 1 g IV'], answer: 1, rationale: 'Major surgery: hydrocortisone 100 mg before induction + 50-100 mg q8h × 24-48h. Endogenous cortisol output during major surgery is 75-150 mg/day cortisol equivalent.' },
  { id: 82, section: 3, q: 'Which anticholinergic has the LEAST central nervous system effect because it does not cross the blood-brain barrier?', options: ['Atropine', 'Scopolamine', 'Glycopyrrolate', 'Hyoscine', 'Benztropine'], answer: 2, rationale: 'Glycopyrrolate is a quaternary amine — charged at physiologic pH and does NOT cross the BBB → no central effects. Atropine and scopolamine are tertiary amines and cross the BBB.' },
  { id: 83, section: 3, q: 'Dantrolene\'s mechanism in malignant hyperthermia is:', options: ['Acetylcholinesterase inhibition at NMJ', 'Block of the ryanodine receptor (RyR1), preventing Ca²⁺ release from sarcoplasmic reticulum', 'Beta-blockade', 'Sodium channel block in skeletal muscle', 'Antagonism of nicotinic receptors'], answer: 1, rationale: 'Dantrolene binds the RyR1 receptor on the sarcoplasmic reticulum, blocking calcium release. Dose: 2.5 mg/kg IV bolus, repeat q5-10 min until stable (up to 10+ mg/kg).' },
  { id: 84, section: 3, q: 'Prolonged high-dose sodium nitroprusside infusion is most associated with:', options: ['Reflex bradycardia', 'Cyanide and thiocyanate toxicity', 'Severe metabolic alkalosis', 'Profound diuresis', 'Rebound hypotension'], answer: 1, rationale: 'SNP releases NO + 5 cyanide ions per molecule. Toxicity risk: doses >2 mcg/kg/min for >24h. Signs: metabolic acidosis, ↑mixed venous O₂ (cells can\'t extract O₂). Treat with hydroxocobalamin.' },
  { id: 85, section: 3, q: 'Sudden discontinuation of chronic beta-blockers preoperatively is associated with increased risk of:', options: ['Bronchospasm only', 'Rebound hypertension, tachycardia, and myocardial ischemia', 'Heart failure exacerbation only', 'Hypoglycemia unawareness only', 'Atrioventricular block'], answer: 1, rationale: 'Chronic beta-blocker therapy upregulates β receptors. Abrupt cessation → rebound hyperadrenergic state → HTN, tachycardia, ischemia, MI. Always continue beta-blockers perioperatively.' },
  { id: 86, section: 3, q: 'ACE inhibitors and ARBs are typically held the morning of surgery because of risk of:', options: ['Rebound hypertension', 'Refractory intraoperative hypotension', 'Bradycardia', 'Hyperkalemia', 'Cough'], answer: 1, rationale: 'ACE inhibitors and ARBs are associated with profound, vasopressor-resistant hypotension on induction. Treat with vasopressin (1-2 U IV) or methylene blue if catecholamine-refractory.' },
  { id: 87, section: 3, q: 'A patient on chronic amitriptyline receives ephedrine intraoperatively and develops a severe hypertensive crisis. The mechanism is:', options: ['MAO inhibition with tyramine accumulation', 'Inhibition of presynaptic NE reuptake — exaggerated indirect sympathomimetic response', 'Serotonin syndrome', 'Anticholinergic crisis', 'Disinhibition of central α2 receptors'], answer: 1, rationale: 'TCAs block NE reuptake → more NE in synapse. Indirect sympathomimetics (ephedrine) cause exaggerated hypertensive responses. Prefer direct-acting agents (phenylephrine, NE) at lower doses.' },
  { id: 88, section: 3, q: 'Which combination is most likely to precipitate serotonin syndrome?', options: ['Fentanyl + dexmedetomidine', 'Meperidine + MAOI', 'Ketamine + propofol', 'Bupivacaine + epinephrine', 'Sugammadex + rocuronium'], answer: 1, rationale: 'Serotonin syndrome (mental status change, autonomic instability, neuromuscular hyperactivity) is precipitated by serotonergic combinations. Meperidine + MAOI = ABSOLUTE contraindication.' },
  { id: 89, section: 3, q: 'The volume of distribution (Vd) of a highly lipid-soluble drug is best characterized as:', options: ['Small, approximating plasma volume (~3 L)', 'Equal to extracellular fluid (~14 L)', 'Equal to total body water (~42 L)', 'Large, often exceeding total body water due to tissue sequestration', 'Always equal to blood volume'], answer: 3, rationale: 'Highly lipid-soluble drugs (fentanyl, propofol, amiodarone) distribute into adipose and other tissues → Vd can be hundreds of liters, far exceeding body water.' },
  { id: 90, section: 3, q: 'First-order elimination kinetics imply:', options: ['A constant amount of drug is eliminated per unit time', 'A constant fraction of drug is eliminated per unit time', 'Elimination is independent of plasma concentration', 'Half-life increases with concentration', 'Clearance equals zero'], answer: 1, rationale: 'First-order: constant FRACTION eliminated per unit time → exponential decay, constant half-life. Zero-order: constant AMOUNT per unit time (ethanol, phenytoin at high doses).' },
  { id: 91, section: 3, q: 'Context-sensitive half-time (CSHT) refers to:', options: ['The terminal elimination half-life', 'Time for plasma concentration to drop 50% after stopping a continuous infusion of varying duration', 'Time to reach steady state', 'Half-life of the active metabolite', 'Time to peak effect'], answer: 1, rationale: 'CSHT = time for plasma concentration to fall 50% after an infusion of a given duration is stopped. Remifentanil ~3-5 min flat; fentanyl rises sharply after 2 h; propofol ~10-20 min.' },
  { id: 92, section: 3, q: 'A drug with high hepatic extraction ratio (>0.7) has clearance that is most dependent on:', options: ['Plasma protein binding', 'Hepatic enzyme activity', 'Hepatic blood flow', 'Renal function', 'Volume of distribution'], answer: 2, rationale: 'High-extraction drugs (propofol, fentanyl, lidocaine, morphine, propranolol) have clearance limited by hepatic blood flow — anything decreasing liver flow decreases clearance.' },
  { id: 93, section: 3, q: 'The second gas effect refers to:', options: ['Faster uptake of a low-soluble gas when given with a high-soluble gas', 'Increased alveolar concentration of a "second gas" (e.g., volatile) when given concurrently with a high-volume gas (N₂O)', 'Concentration effect in arterial blood', 'Diffusion hypoxia at emergence', 'Decreased FRC during induction'], answer: 1, rationale: 'Second gas effect: large-volume uptake of N₂O creates a concentrating effect on co-administered volatile agent, accelerating its alveolar concentration rise and onset.' },
  { id: 94, section: 3, q: 'MAC-BAR (block adrenergic response) and MAC-awake compare to MAC-1 as follows:', options: ['MAC-awake ~ 0.3-0.5 × MAC; MAC-BAR ~ 1.5 × MAC', 'MAC-awake ~ 1.5 × MAC; MAC-BAR ~ 0.3 × MAC', 'Both equal MAC-1', 'MAC-awake = 2 × MAC; MAC-BAR = 0.5 × MAC', 'Variable, not standardized'], answer: 0, rationale: 'MAC-awake (prevents recall/eye opening) ≈ 0.3-0.5 × MAC. MAC-BAR (blocks adrenergic response) ≈ 1.5 × MAC. MAC-intubation ≈ 1.3 × MAC.' },
  { id: 95, section: 3, q: 'Nitrous oxide is relatively contraindicated in all of the following EXCEPT:', options: ['Pneumothorax', 'Bowel obstruction with air-filled loops', 'Recent pneumoencephalography or middle ear surgery', 'Pulmonary hypertension', 'Awake fiberoptic intubation'], answer: 4, rationale: 'N₂O is 34× more soluble than nitrogen → diffuses into and expands air-filled spaces. It has NO contraindication for awake fiberoptic intubation — minimal effect on hemodynamics or airway reflexes.' },
  { id: 96, section: 3, q: 'Lithium prolongs the effect of which anesthetic class?', options: ['Volatile anesthetics only', 'Both depolarizing and nondepolarizing neuromuscular blockers', 'Opioids only', 'Local anesthetics', 'Benzodiazepines'], answer: 1, rationale: 'Lithium prolongs both succinylcholine and nondepolarizing NMB action by interfering with NMJ sodium handling. Also reduces MAC.' },
  { id: 97, section: 3, q: 'The mechanism of unfractionated heparin is:', options: ['Direct inhibition of thrombin (factor IIa) only', 'Vitamin K antagonism', 'Acceleration of antithrombin III\'s inhibition of thrombin and factor Xa', 'Inhibition of factor V Leiden', 'Inhibition of platelet COX-1'], answer: 2, rationale: 'Heparin binds antithrombin III and accelerates its inhibition of factors IIa, IXa, Xa, XIa, XIIa (1000-fold). UFH inhibits IIa and Xa equally; LMWH preferentially inhibits Xa.' },
  { id: 98, section: 3, q: 'Severe reactions to protamine include all EXCEPT:', options: ['Histamine-mediated hypotension', 'Anaphylactic reactions (especially in patients on NPH insulin or with fish allergy)', 'Pulmonary hypertension and right heart failure', 'Hyperkalemia', 'Profound systemic hypotension if injected rapidly'], answer: 3, rationale: 'Protamine reactions: (1) rapid-injection hypotension (histamine), (2) anaphylactoid (NPH insulin users, fish allergy), (3) catastrophic pulmonary vasoconstriction with RV failure. Hyperkalemia is NOT a protamine effect.' },
  { id: 99, section: 3, q: 'Tranexamic acid (TXA) prevents bleeding by:', options: ['Direct factor Xa inhibition', 'Inhibiting plasminogen binding to fibrin (antifibrinolytic)', 'Activating antithrombin', 'Inhibiting platelet aggregation', 'Vitamin K supplementation'], answer: 1, rationale: 'TXA (and aminocaproic acid) are lysine analogs that competitively block plasminogen binding to fibrin → reduce fibrinolysis. CRASH-2 and WOMAN trials demonstrated mortality benefit within 3 hours.' },
  { id: 100, section: 3, q: 'Adenosine 6 mg IV is given for narrow-complex SVT. Expected effects include all EXCEPT:', options: ['Transient AV nodal block', 'Brief asystole (3-10 seconds)', 'Flushing and chest discomfort', 'Bronchospasm in asthmatics', 'Prolonged QT >500 ms'], answer: 4, rationale: 'Adenosine activates A1 receptors → transient AV block (half-life ~10 sec). Side effects: flushing, dyspnea, chest pain, bronchospasm (avoid in severe asthma), brief asystole. Does NOT prolong QT.' },

  // SECTION 4 — EQUIPMENT (101-120)
  { id: 101, section: 4, q: 'The fail-safe valve on the anesthesia machine protects against:', options: ['Delivery of a hypoxic mixture if N₂O fails', 'Loss of oxygen supply pressure', 'Vaporizer overfilling', 'Reverse flow of waste gases', 'Excess airway pressure'], answer: 1, rationale: 'The fail-safe valve shuts off N₂O if oxygen supply pressure drops below ~25 psi — but does NOT prevent a hypoxic mixture if the O₂ flowmeter is turned down. The proportioning system (Link 25, ORMC) prevents <25% O₂ mixtures.' },
  { id: 102, section: 4, q: 'Which check should be performed BEFORE turning on the anesthesia machine?', options: ['Positive pressure leak test of the breathing circuit', 'Check of pipeline pressures (50 psi)', 'Cylinder check (E-cylinders ≥1000 psi for O₂)', 'Vaporizer fill level', 'All of the above'], answer: 4, rationale: 'Pre-use checkout: pipeline supplies/pressures, backup cylinder check, vaporizer fill, leak/circuit integrity tests, ventilator/scavenger function, monitors calibrated, suction and emergency equipment.' },
  { id: 103, section: 4, q: 'Variable-orifice (rotameter) flowmeters depend on which gas property at low flows and which at high flows?', options: ['Density at low, viscosity at high', 'Viscosity at low, density at high', 'Solubility at low, density at high', 'Both depend equally on density', 'Temperature only'], answer: 1, rationale: 'Rotameters: at low flows (laminar), flow depends on viscosity (Poiseuille); at high flows (turbulent), flow depends on density (Reynolds). This is why flowmeters are gas-specific and non-interchangeable.' },
  { id: 104, section: 4, q: 'Desflurane requires a heated, pressurized vaporizer (TEC 6/Aladin cassette) because:', options: ['It has very high MAC', 'Its vapor pressure approaches atmospheric pressure at room temperature (boiling point 22.8°C)', 'It is unstable in soda lime', 'It reacts with metal components', 'It has high blood:gas solubility'], answer: 1, rationale: 'Desflurane BP 22.8°C and high vapor pressure (~700 mmHg at 20°C) would cause boiling in conventional vaporizers. The TEC 6 heats desflurane to 39°C (2 atm) for precise metering.' },
  { id: 105, section: 4, q: 'Carbon monoxide production by desiccated soda lime is greatest with which volatile?', options: ['Halothane', 'Isoflurane', 'Sevoflurane', 'Desflurane', 'Nitrous oxide'], answer: 3, rationale: 'CO production from desiccated absorbents: Des > Iso > Sevo. Greatest risk is the FIRST CASE OF MONDAY when absorbent has dried out from high O₂ flow over the weekend.' },
  { id: 106, section: 4, q: 'The pin index safety system (PISS) on E-cylinders prevents:', options: ['Reverse gas flow', 'Connection of the wrong gas cylinder to the yoke', 'Cylinder overpressure', 'Cross-contamination of cylinders', 'Hypoxic gas mixtures'], answer: 1, rationale: 'PISS uses two pins on the yoke that must match holes on the cylinder valve — each gas has a unique pin configuration (O₂: 2-5; N₂O: 3-5; Air: 1-5).' },
  { id: 107, section: 4, q: 'A full E-cylinder of oxygen has a pressure of 1900 psi and contains approximately:', options: ['330 L', '660 L', '1600 L', '1900 L', '5000 L'], answer: 1, rationale: 'Full O₂ E-cylinder: 1900 psi, ~660 L of gas. Calculate remaining volume: (current psi/1900) × 660. N₂O E-cylinder: 745 psi, 1590 L (liquid inside — pressure stays constant until ~75% empty).' },
  { id: 108, section: 4, q: 'Pulse oximetry is most likely to read falsely LOW in:', options: ['Carboxyhemoglobinemia', 'Methemoglobinemia at high levels', 'Methylene blue or indigo carmine dye administration', 'Polycythemia', 'Hypothermia'], answer: 2, rationale: 'Methylene blue, indigo carmine, and indocyanine green absorb at 660 nm → falsely LOW SpO₂. COHb reads falsely HIGH (reads as oxyHb). MetHb drives reading toward 85% regardless of true sat.' },
  { id: 109, section: 4, q: 'A sudden decrease in end-tidal CO₂ from 38 to 8 mmHg in a stable intubated patient most likely indicates:', options: ['Hyperventilation', 'Pulmonary embolism or circuit disconnect', 'Hypoventilation', 'Increased dead space from increased PEEP', 'Soda lime exhaustion'], answer: 1, rationale: 'Sudden, dramatic ETCO₂ drop suggests: circuit disconnect/extubation (most common), cardiac arrest, massive PE, capnograph malfunction. "No CO₂ = no chance" — always confirm tube placement.' },
  { id: 110, section: 4, q: 'A "shark fin" shaped capnograph waveform is characteristic of:', options: ['Normal ventilation', 'Endobronchial intubation', 'Bronchospasm or upper airway obstruction (e.g., COPD, asthma, kinked ETT)', 'Rebreathing of CO₂', 'Esophageal intubation'], answer: 2, rationale: 'Sloping or "shark fin" phase III plateau indicates expiratory airflow obstruction — bronchospasm, kinked ETT, mucus plug, COPD.' },
  { id: 111, section: 4, q: 'A non-invasive blood pressure cuff that is too small for the arm circumference will read:', options: ['Falsely high', 'Falsely low', 'Accurately if the patient is supine', 'No measurable BP', 'Variably high or low'], answer: 0, rationale: 'Too small cuff → falsely HIGH BP (requires more pressure to occlude). Too large cuff → falsely LOW.' },
  { id: 112, section: 4, q: 'An over-damped arterial waveform results in:', options: ['Falsely high systolic, falsely low diastolic, accurate mean', 'Falsely low systolic, falsely high diastolic, accurate mean', 'Accurate systolic and diastolic', 'Inaccurate mean only', 'Higher pulse pressure'], answer: 1, rationale: 'OVER-damping: narrowed pulse pressure (systolic underestimated, diastolic overestimated), MAP usually accurate. UNDER-damping: exaggerated systolic and resonance/whip.' },
  { id: 113, section: 4, q: 'Which TEE view is best to assess for left ventricular wall motion abnormalities in all three coronary distributions?', options: ['Midesophageal four-chamber', 'Midesophageal long-axis', 'Transgastric short-axis (mid-papillary)', 'Midesophageal aortic valve short-axis', 'Bicaval view'], answer: 2, rationale: 'Transgastric mid-papillary short-axis displays all three coronary territories — LAD (anterior, anteroseptal), LCX (lateral), RCA (inferior, inferoseptal) — simultaneously.' },
  { id: 114, section: 4, q: 'PCWP (pulmonary capillary wedge pressure) approximates which left-sided pressure?', options: ['Left ventricular end-systolic pressure', 'Left atrial pressure ≈ left ventricular end-diastolic pressure', 'Mean arterial pressure', 'Left ventricular outflow tract pressure', 'Coronary perfusion pressure'], answer: 1, rationale: 'PCWP ≈ LAP ≈ LVEDP in the absence of mitral valve disease, high PEEP, or pulmonary venous obstruction. Normal: 6-12 mmHg.' },
  { id: 115, section: 4, q: 'The ECG lead most sensitive for detecting LATERAL wall ischemia is:', options: ['Lead II', 'Lead V1', 'Lead V3', 'Lead V5', 'Lead aVR'], answer: 3, rationale: 'V5 (lateral wall — LAD/LCX territory) detects ~80% of intraoperative ischemia events. Standard intraop: 5-lead ECG with leads II + V5.' },
  { id: 116, section: 4, q: 'Which site most accurately reflects core body temperature?', options: ['Axilla', 'Skin', 'Tympanic membrane or distal esophagus', 'Bladder during low urine output', 'Nasopharyngeal during nasal O₂'], answer: 2, rationale: 'Best core sites: pulmonary artery (gold standard), distal esophagus (lower 1/3), tympanic membrane, nasopharynx. Skin/axillary 1-2°C below core.' },
  { id: 117, section: 4, q: 'A train-of-four (TOF) ratio of 0.7 in the recovery room is associated with:', options: ['Adequate reversal', 'Pharyngeal dysfunction and aspiration risk', 'Complete paralysis', 'Phase II block', 'Normal swallowing'], answer: 1, rationale: 'Residual paralysis (TOF ratio <0.9) impairs pharyngeal coordination, hypoxic ventilatory response, and protective reflexes → aspiration risk. Quantitative monitors recommended.' },
  { id: 118, section: 4, q: 'A BIS (bispectral index) value of 40-60 is targeted to:', options: ['Detect awake patients', 'Provide deep general anesthesia with low awareness risk', 'Confirm brain death', 'Optimize PACU recovery', 'Predict mortality'], answer: 1, rationale: 'BIS scale: 100 (awake) → 70-90 (sedation) → 40-60 (GA target) → <40 (deep, burst suppression) → 0 (isoelectric). BIS-guided anesthesia may reduce awareness in high-risk patients.' },
  { id: 119, section: 4, q: 'A Mapleson D circuit during spontaneous ventilation requires fresh gas flow of approximately:', options: ['1× minute ventilation', '1.5-2× minute ventilation', '2-3× minute ventilation', '0.5× minute ventilation', 'Only the patient\'s tidal volume'], answer: 2, rationale: 'Mapleson efficiency: spontaneous A > DFE > CB; controlled DFE > BC > A. Mapleson D needs ~2-3× MV during spontaneous breathing to prevent rebreathing. Mapleson A (Magill) is most efficient for spontaneous.' },
  { id: 120, section: 4, q: 'During laryngeal laser surgery, which precaution most reduces airway fire risk?', options: ['Use FiO₂ < 30% (or air-helium mix), N₂O-free, with a laser-resistant ETT and saline-filled cuff', 'Use 100% O₂ with thiopental induction', 'Use a standard PVC ETT', 'Use LMA only', 'Avoid muscle relaxant'], answer: 0, rationale: 'Airway fire triad: oxidizer (O₂, N₂O), fuel (ETT), ignition (laser). Prevention: FiO₂ < 30%, no N₂O, laser-safe ETT, saline ± methylene blue in cuff.' },

  // SECTION 5 — MONITORING & CLINICAL (121-150)
  { id: 121, section: 5, q: 'ASA fasting guidelines for an elective procedure recommend NPO for clear liquids of at least:', options: ['1 hour', '2 hours', '4 hours', '6 hours', '8 hours'], answer: 1, rationale: 'ASA NPO guidelines: 2 h clear liquids, 4 h breast milk, 6 h infant formula/light meal/non-human milk, 8 h fatty meals.' },
  { id: 122, section: 5, q: 'A Mallampati class IV airway describes which oropharyngeal view?', options: ['Soft palate, uvula, pillars all visible', 'Soft palate and uvula visible', 'Soft palate and base of uvula visible', 'Only hard palate visible', 'Soft palate not visible'], answer: 3, rationale: 'Mallampati: I = soft palate, uvula, pillars, fauces; II = soft palate, uvula, pillars; III = soft palate, base of uvula; IV = hard palate only.' },
  { id: 123, section: 5, q: 'The "sniffing position" optimizes laryngoscopy by aligning:', options: ['Oral, pharyngeal, and laryngeal axes', 'Cervical lordosis only', 'Mandible and hyoid only', 'Vocal cords with the trachea', 'Soft palate with hard palate'], answer: 0, rationale: 'Sniffing position (head elevated ~8-10 cm + atlanto-occipital extension) aligns the oral, pharyngeal, and laryngeal axes for direct laryngoscopy.' },
  { id: 124, section: 5, q: 'After 2 failed intubation attempts and inability to mask ventilate, the next priority per ASA difficult airway algorithm is:', options: ['A third intubation attempt with different blade', 'Emergency invasive airway access (cricothyroidotomy)', 'Place an LMA or supraglottic airway as a rescue device', 'Awaken the patient', 'Tracheostomy'], answer: 2, rationale: 'Cannot intubate, cannot ventilate (CICV): place supraglottic device (LMA, iGel, King) as rescue first. If unsuccessful → emergency invasive airway (cricothyrotomy).' },
  { id: 125, section: 5, q: 'Rapid sequence induction (RSI) classically includes:', options: ['Preoxygenation, cricoid pressure (controversial), no mask ventilation, rapid induction + sux 1-1.5 mg/kg (or rocuronium 1.2 mg/kg)', 'Sevoflurane induction with cricoid pressure', 'Awake fiberoptic intubation', 'Standard induction with delayed muscle relaxant', 'Conscious sedation'], answer: 0, rationale: 'RSI: preoxygenate to ETCO₂ ≥0.85, rapid induction agent, succinylcholine 1-1.5 mg/kg or rocuronium 1.2 mg/kg, NO mask ventilation, intubate at 45-60 s.' },
  { id: 126, section: 5, q: 'Mendelson described aspiration pneumonitis with gastric contents of pH and volume:', options: ['pH > 4.0, volume > 10 mL', 'pH < 2.5, volume > 25 mL (~0.4 mL/kg)', 'pH > 7, any volume', 'pH < 6, volume > 100 mL', 'Volume only, pH irrelevant'], answer: 1, rationale: 'Mendelson (1946): chemical pneumonitis when pH <2.5 AND volume >25 mL (~0.4 mL/kg). Risk factors: full stomach, pregnancy, GERD, obesity, diabetic gastroparesis, opioids.' },
  { id: 127, section: 5, q: 'Hypotension after spinal anesthesia at T6 is primarily due to:', options: ['Vagal stimulation', 'Sympathectomy with decreased SVR and venous pooling', 'Direct cardiac depression from local anesthetic', 'Bradycardia from blockade of cardiac accelerators (T1-T4)', 'Both B and D contribute, with B being primary'], answer: 4, rationale: 'Spinal hypotension: sympathectomy → ↓preload (venous pooling) is primary. High blocks (≥T4) also block cardiac accelerators → bradycardia. Treat: LUD, fluids, phenylephrine ± ephedrine.' },
  { id: 128, section: 5, q: 'A post-dural puncture headache (PDPH) classically:', options: ['Is worse lying flat and improves standing', 'Is unrelated to position', 'Is worse standing/sitting and improves lying flat', 'Resolves within hours regardless of treatment', 'Is bitemporal and throbbing only'], answer: 2, rationale: 'PDPH from CSF leak: POSITIONAL — worse upright, better supine. Frontal/occipital. Definitive treatment: epidural blood patch (15-20 mL autologous blood). 70-90% success on first patch.' },
  { id: 129, section: 5, q: 'The most serious neurologic complication of neuraxial anesthesia is:', options: ['Transient neurologic symptoms', 'Headache', 'Epidural hematoma (especially with anticoagulation)', 'Cauda equina syndrome from lidocaine 5%', 'Backache'], answer: 2, rationale: 'Epidural hematoma: cord compression presenting as progressive lower limb weakness/sensory loss, back pain, bladder/bowel dysfunction. Emergent MRI + decompression within 6-12 h preserves neurologic function.' },
  { id: 130, section: 5, q: 'The classic 1:1:1 ratio in massive transfusion refers to:', options: ['PRBC : platelets : crystalloid', 'PRBC : FFP : platelets (as approximate whole blood equivalent)', 'Crystalloid : colloid : blood', 'Albumin : FFP : PRBC', 'Cryoprecipitate : FFP : PRBC'], answer: 1, rationale: 'PROPPR trial: 1:1:1 (PRBC:FFP:platelets) — early balanced resuscitation reduces dilutional coagulopathy and achieves earlier hemostasis.' },
  { id: 131, section: 5, q: 'Citrate toxicity from rapid blood transfusion presents primarily as:', options: ['Hyperkalemia', 'Ionized hypocalcemia with hypotension and QT prolongation', 'Hyperphosphatemia', 'Acidosis only', 'Hyperthermia'], answer: 1, rationale: 'Citrate (anticoagulant in stored blood) chelates Ca²⁺ → ionized hypocalcemia → hypotension, prolonged QT. Treat with CaCl₂ (10 mg/kg) or gluconate (30 mg/kg).' },
  { id: 132, section: 5, q: 'Transfusion-related acute lung injury (TRALI) is characterized by:', options: ['Hypoxemia and bilateral pulmonary infiltrates within 6 h of transfusion, no other cause, no volume overload', 'Delayed hemolytic reaction', 'Hyperkalemia and acidosis', 'Anaphylactoid reaction with bronchospasm', 'Septic shock from contaminated blood'], answer: 0, rationale: 'TRALI: leading cause of transfusion mortality. Donor antibodies (anti-HLA, anti-HNA) activate recipient neutrophils. Onset <6 h. Distinguish from TACO (diuretic-responsive volume overload).' },
  { id: 133, section: 5, q: 'Compared with normal saline, lactated Ringer\'s solution is associated with:', options: ['More hyperchloremic metabolic acidosis', 'Less hyperchloremic acidosis and possibly better AKI outcomes', 'Calcium incompatibility — never co-infuse with citrated blood', 'Both B and C', 'Hyperkalemia in renal failure'], answer: 3, rationale: 'LR has more physiologic chloride (109 vs 154 mEq/L) → less hyperchloremic acidosis. SMART/SALT-ED trials suggest balanced crystalloids reduce AKI. LR also contains calcium — traditionally considered incompatible with citrated blood.' },
  { id: 134, section: 5, q: 'Hydroxyethyl starch (HES) for resuscitation is now restricted because of:', options: ['Hypotension on rapid infusion', 'Increased AKI and mortality in septic and critically ill patients', 'Coagulopathy alone', 'Hyperkalemia', 'Anaphylaxis only'], answer: 1, rationale: 'VISEP, 6S, CHEST trials demonstrated HES increased AKI and mortality vs crystalloid in septic/critically ill patients. EMA and FDA restricted HES use.' },
  { id: 135, section: 5, q: 'Major risk factors for PONV per Apfel score include all EXCEPT:', options: ['Female sex', 'Non-smoker', 'History of PONV or motion sickness', 'Postoperative opioids', 'Age > 65'], answer: 4, rationale: 'Apfel score: female, non-smoker, history of PONV/motion sickness, postop opioids — each = 1 point. Older age is associated with LESS PONV.' },
  { id: 136, section: 5, q: 'A modified Aldrete score for PACU discharge to a regular floor typically requires:', options: ['>5 of 10', '≥9 of 10 with stable vital signs', 'Pain score = 0', 'No nausea', 'Walking unassisted'], answer: 1, rationale: 'Aldrete score (5 categories × 2 pts): activity, respiration, circulation, consciousness, oxygenation. Discharge to floor at ≥9.' },
  { id: 137, section: 5, q: 'Risk factors for intraoperative awareness include all EXCEPT:', options: ['TIVA without depth monitoring', 'Cardiac surgery and obstetric general anesthesia', 'Trauma cases', 'Use of muscle relaxants without volatile anesthetic', 'ASA I, elective hernia repair'], answer: 4, rationale: 'Awareness risk: trauma, cardiac, OB GA, difficult intubation, equipment malfunction, NMB without adequate anesthetic depth, TIVA without monitoring, history of awareness. ASA I elective hernia is low risk.' },
  { id: 138, section: 5, q: 'An active scavenging system with an open reservoir requires which connection feature?', options: ['Positive pressure relief valve only', 'Negative pressure relief valve only', 'Both positive and negative pressure relief', 'No relief valves', 'Closed reservoir only'], answer: 2, rationale: 'Active CLOSED reservoir scavenging requires both positive AND negative pressure relief valves. Active OPEN reservoir: open to atmosphere — no relief valves needed.' },
  { id: 139, section: 5, q: 'Pulse oximetry uses wavelengths of:', options: ['520 and 660 nm', '660 and 940 nm', '800 and 920 nm', 'Single wavelength 700 nm', 'UV 280 nm'], answer: 1, rationale: 'Pulse oximetry: 660 nm (red — absorbed more by deoxyHb) and 940 nm (infrared — absorbed more by oxyHb). Ratio of absorbances → SpO₂.' },
  { id: 140, section: 5, q: 'Synchronized cardioversion for stable atrial fibrillation typically begins at:', options: ['50 J biphasic', '100-200 J biphasic', '360 J monophasic only', '10 J', 'Defibrillation, not cardioversion'], answer: 1, rationale: 'ACLS cardioversion energies (biphasic): a-fib 120-200 J, a-flutter/SVT 50-100 J, VT with pulse 100 J. UNSYNCHRONIZED defibrillation for pulseless VT/VF.' },
  { id: 141, section: 5, q: 'Electrical interference of unipolar electrocautery with a pacemaker is best minimized by:', options: ['Placing the return pad close to the pacemaker', 'Using bipolar cautery and placing the return pad as far from the device as possible, with short bursts', 'Setting the pacemaker to asynchronous mode in all cases', 'Using monopolar cautery in short bursts only', 'Removing the pacemaker'], answer: 1, rationale: 'Cautery EMI may cause pacemaker oversensing → asystole or reprogramming. Mitigations: bipolar > monopolar, short bursts (<5 sec), return pad away from device, magnet over pacer if needed.' },
  { id: 142, section: 5, q: 'An awake fiberoptic intubation typically uses topical anesthesia of:', options: ['Lidocaine 4% nebulized + glossopharyngeal/superior laryngeal/translaryngeal blocks', 'Bupivacaine 0.5% topical', 'Cocaine 10% in all cases', 'Procaine spray', 'Articaine subcutaneous'], answer: 0, rationale: 'Awake FOI prep: antisialagogue (glyco), 4% lidocaine (nebulized, atomized, spray-as-you-go), bilateral SLN block at greater cornu of hyoid, glossopharyngeal block, ± translaryngeal injection. Dexmedetomidine sedation preserves airway.' },
  { id: 143, section: 5, q: 'Sciatic nerve block does NOT cover which area of the lower limb?', options: ['Posterior thigh and entire foot below the knee EXCEPT the medial aspect (saphenous nerve, femoral branch)', 'Lateral foot only', 'Plantar surface', 'Tibial nerve distribution', 'Common peroneal distribution'], answer: 0, rationale: 'Sciatic nerve (tibial + common peroneal) covers posterior thigh, leg, and foot below knee EXCEPT medial leg/medial foot (saphenous nerve, terminal of femoral).' },
  { id: 144, section: 5, q: 'The most common complication of an interscalene block is:', options: ['Pneumothorax', 'Phrenic nerve block with ipsilateral hemidiaphragm paresis (nearly 100%)', 'Horner\'s syndrome', 'Recurrent laryngeal nerve block', 'All of the above can occur; phrenic is nearly universal'], answer: 4, rationale: 'Interscalene: phrenic ~100%, Horner\'s ~30-50%, RLN block (hoarseness), pneumothorax (low with US). Phrenic palsy is a near-universal side effect.' },
  { id: 145, section: 5, q: 'Ultrasound-guided supraclavicular block has highest pneumothorax risk because of proximity to:', options: ['The carotid artery', 'The pleural dome', 'The trachea', 'The phrenic nerve', 'The vagus nerve'], answer: 1, rationale: 'Supraclavicular block targets brachial plexus trunks over the first rib, adjacent to the pleural dome. Pneumothorax incidence historically ~6% landmark; <1% with US.' },
  { id: 146, section: 5, q: 'ACC/AHA guidelines recommend continuing which medication on the morning of non-cardiac surgery?', options: ['Beta-blockers (if chronic)', 'ACE inhibitors for hypertension', 'ARBs for HTN', 'Diuretics', 'Insulin secretagogues (sulfonylureas) full dose'], answer: 0, rationale: 'Continue: beta-blockers (avoid abrupt withdrawal), statins, antianginal therapy. Hold morning of surgery: ACE/ARBs (refractory hypotension), diuretics, sulfonylureas (hypoglycemia), SGLT-2 (euglycemic DKA — hold 3-4 days).' },
  { id: 147, section: 5, q: 'A patient with a drug-eluting stent (DES) placed 8 months ago for an MI requires non-cardiac surgery. Optimal management is:', options: ['Delay surgery 12 months from PCI; continue ASA; consider holding P2Y12 inhibitor for 5-7 days', 'Stop ASA and P2Y12 inhibitors immediately', 'Proceed without delay', 'Cancel all elective surgery indefinitely', 'Bridge with heparin only'], answer: 0, rationale: 'DES + ACS: DAPT for ≥12 months; elective surgery delayed until DAPT complete. After 12 mo, may interrupt P2Y12 for urgent surgery while continuing aspirin.' },
  { id: 148, section: 5, q: 'Volume-control ventilation in the OR is most likely to produce barotrauma in:', options: ['Severely emphysematous patients', 'Healthy elective cases', 'Neonates', 'Patients with high oxygen requirements', 'All of the above except B'], answer: 0, rationale: 'VCV delivers set tidal volume regardless of pressure — high airway pressures and barotrauma in high-resistance/low-compliance lungs (emphysema, bronchospasm).' },
  { id: 149, section: 5, q: 'The benefit of pressure-controlled (PCV) ventilation over volume-controlled (VCV) ventilation includes:', options: ['Always higher tidal volumes', 'Decelerating flow pattern with more even gas distribution and lower peak airway pressure', 'Guaranteed minute ventilation', 'Better for non-compliant lungs only', 'No effect on hemodynamics'], answer: 1, rationale: 'PCV: decelerating inspiratory flow → more even alveolar filling, lower peak airway pressure, better gas exchange. Disadvantage: tidal volume varies with compliance/resistance.' },
  { id: 150, section: 5, q: 'Intraoperative lung-protective ventilation per current evidence includes:', options: ['TV 10 mL/kg IBW, PEEP 0, FiO₂ 1.0', 'TV 6-8 mL/kg IBW, PEEP 5+ cmH₂O, recruitment maneuvers, lowest tolerated FiO₂', 'TV 12 mL/kg actual body weight, no PEEP', 'PCV with peak pressures >40 cmH₂O', 'High respiratory rate only'], answer: 1, rationale: 'Lung-protective ventilation: TV 6-8 mL/kg IBW, PEEP 5+, Pplat <16-18 cmH₂O, periodic recruitment, FiO₂ lowest to keep SpO₂ ≥92%. Reduces postoperative pulmonary complications.' },

  // SECTION 6 — OB & PEDS (151-170)
  { id: 151, section: 6, q: 'All of the following physiologic changes occur during pregnancy EXCEPT:', options: ['Increased cardiac output by 30-50%', 'Decreased functional residual capacity by 20%', 'Increased plasma volume more than RBC mass (dilutional anemia)', 'Decreased MAC by ~30%', 'Decreased gastric emptying with increased lower esophageal sphincter tone'], answer: 4, rationale: 'Pregnancy: ↑CO 30-50%, ↓FRC 20%, ↑plasma volume >RBC mass, ↓MAC 30%, ↑aspiration risk from progesterone-mediated DECREASED LES tone. Gastric emptying SLOWS after labor onset.' },
  { id: 152, section: 6, q: 'Aortocaval compression in a term parturient supine results in:', options: ['Maternal hypotension and decreased uterine perfusion', 'Increased venous return', 'Maternal tachycardia only without hemodynamic effect', 'Fetal bradycardia only', 'Maternal bradycardia from vagal reflex'], answer: 0, rationale: 'After ~20 weeks, supine position → IVC and aortic compression → ↓venous return → ↓CO → maternal hypotension AND ↓uterine perfusion. Always tilt 15° left.' },
  { id: 153, section: 6, q: 'The most common cause of anesthesia-related maternal mortality is:', options: ['Local anesthetic toxicity from epidural', 'Difficult airway/failed intubation with hypoxemia and aspiration', 'Hemorrhage', 'Amniotic fluid embolism', 'Eclampsia'], answer: 1, rationale: 'Airway problems remain a leading anesthesia-related cause of maternal death. Pregnancy → airway edema, weight gain, large breasts, ↑Mallampati class, ↓FRC → rapid desaturation.' },
  { id: 154, section: 6, q: 'The visceral pain of first-stage labor is transmitted via:', options: ['T10-L1 sympathetic afferents', 'T6-T9 only', 'S2-S4 parasympathetic afferents only', 'Pudendal (S2-S4) only', 'Both T10-L1 and S2-S4'], answer: 0, rationale: 'First stage labor: visceral pain via T10-L1 sympathetic afferents (uterine contractions, cervical dilation). Second stage: somatic pain via pudendal nerve (S2-S4) from perineal stretch.' },
  { id: 155, section: 6, q: 'For elective cesarean delivery under spinal anesthesia, the surgical sensory block height required is at least:', options: ['T10', 'T8', 'T6 (xiphoid)', 'T4', 'C5'], answer: 3, rationale: 'Cesarean delivery requires sensory block to T4 (nipple line) to cover uterine traction. T6 alone results in intraoperative discomfort.' },
  { id: 156, section: 6, q: 'Severe features of preeclampsia include all EXCEPT:', options: ['BP ≥160/110', 'Platelets <100,000', 'Elevated transaminases >2× normal', 'Pulmonary edema, persistent headache, visual changes, epigastric pain', 'Proteinuria 0.5 g/24h'], answer: 4, rationale: 'ACOG severe-feature criteria: BP ≥160/110, plt <100k, AST/ALT 2× normal, Cr >1.1, pulmonary edema, new headache/visual symptoms. Proteinuria is no longer required for diagnosis.' },
  { id: 157, section: 6, q: 'Magnesium toxicity becomes apparent at serum levels associated with which sign?', options: ['Loss of patellar reflexes (~9-12 mg/dL)', 'ECG widening at 5-7 mg/dL', 'Cardiac arrest at >7 mg/dL', 'Confusion at 4 mg/dL', 'All occur at the same level'], answer: 0, rationale: 'Mg²⁺ toxicity: loss of DTRs 9-12 mg/dL, respiratory depression 12-15, cardiac arrest >25. Monitor: reflexes, RR, urine output. Reverse with calcium gluconate 1 g IV.' },
  { id: 158, section: 6, q: 'Uterine atony refractory to oxytocin is best treated next with:', options: ['Methylergonovine 0.2 mg IM (caution in HTN)', 'Carboprost (PGF2α) 250 mcg IM — avoid in asthma', 'Misoprostol 800-1000 mcg rectally/sublingually', 'Tranexamic acid 1 g IV (WOMAN trial)', 'Any of the above plus bimanual massage and surgical/IR escalation'], answer: 4, rationale: 'PPH management: oxytocin first, then methylergometrine (not in HTN), carboprost (not in asthma), misoprostol, TXA, bimanual massage, surgical (B-Lynch, hysterectomy), IR embolization.' },
  { id: 159, section: 6, q: 'Amniotic fluid embolism (AFE) classically presents with:', options: ['Slow-developing hypoxemia over 24 h', 'Sudden cardiovascular collapse, hypoxemia, and DIC during labor or shortly postpartum', 'Isolated peripheral edema', 'Hypertension with seizures', 'Postoperative wound infection'], answer: 1, rationale: 'AFE: rare (1 in 40,000) but fatality 20-60%. Triad: sudden cardiovascular collapse, hypoxemia, DIC during labor or within 30 min postpartum. Treatment supportive.' },
  { id: 160, section: 6, q: 'An unintended dural puncture with a 17-gauge Tuohy needle produces PDPH in approximately:', options: ['<5%', '10-20%', '50-80%', '100%', 'Indeterminate'], answer: 2, rationale: 'Dural puncture with 17G Tuohy → PDPH ~50-80% in young parturients. Pencil-point 25G spinal needles: <1-3%. Epidural blood patch definitive treatment — 70-90% success.' },
  { id: 161, section: 6, q: 'Compared to adults, the pediatric airway is characterized by all EXCEPT:', options: ['Larger occiput', 'Higher (more cephalad) larynx (C3-C4 in infants vs C5-C6 in adults)', 'Funnel-shaped (cricoid narrowest)', 'Larger tongue relative to oral cavity', 'Smaller, less floppy epiglottis'], answer: 4, rationale: 'Pediatric airway: large occiput, large tongue, cephalad larynx, long FLOPPY epiglottis (use straight Miller blade), funnel-shaped (cricoid narrowest until age 8), short trachea.' },
  { id: 162, section: 6, q: 'The appropriate cuffed endotracheal tube internal diameter (mm) for a 4-year-old child is approximately:', options: ['3.0', '3.5', '4.5', '5.5', '6.5'], answer: 2, rationale: 'Cuffed ETT formula: (age/4) + 3.5; uncuffed: (age/4) + 4. For age 4: cuffed ~4.5, uncuffed ~5.0. Tube depth (cm at lip) ≈ age/2 + 12, or ID × 3.' },
  { id: 163, section: 6, q: 'Inhalational induction in a healthy 3-year-old is best achieved with:', options: ['Sevoflurane 8% in 70% N₂O / 30% O₂', 'Isoflurane 2% in air', 'Desflurane 12% (despite airway irritability)', 'Halothane 5%', 'IV propofol only'], answer: 0, rationale: 'Sevoflurane is the agent of choice for inhalational induction — non-pungent, no airway irritation, rapid onset; high concentrations (8% with N₂O) for fast induction.' },
  { id: 164, section: 6, q: 'First-line management of laryngospasm in a child is:', options: ['100% O₂, jaw thrust (Larson\'s maneuver — pressure at pre-styloid notch), CPAP', 'Immediate succinylcholine 4 mg/kg IM', 'Awakening the patient', 'Atropine 0.02 mg/kg IV', 'Cricoid pressure'], answer: 0, rationale: 'Laryngospasm: stop stimulus → 100% O₂, jaw thrust with bilateral pressure at the "laryngospasm notch" (Larson\'s maneuver), CPAP, deepen anesthesia. Refractory: succinylcholine 0.1-0.5 mg/kg IV or 4 mg/kg IM.' },
  { id: 165, section: 6, q: 'The 4-2-1 rule for maintenance fluids in a 25-kg child gives an hourly rate of:', options: ['50 mL/h', '65 mL/h', '75 mL/h', '100 mL/h', '150 mL/h'], answer: 1, rationale: '4-2-1: 4 mL/kg/h for first 10 kg, 2 mL/kg/h for next 10 kg, 1 mL/kg/h above 20 kg. For 25 kg: 40 + 20 + 5 = 65 mL/h.' },
  { id: 166, section: 6, q: 'The pediatric POVOC risk score for PONV uses risk factors of:', options: ['Age, sex, weight, BMI', 'Strabismus surgery, age ≥3, prior PONV/family history, anticipated longer surgery', 'Cancer, asthma, diabetes, asthma', 'Anesthetic agent only', 'ASA class only'], answer: 1, rationale: 'POVOC (pediatric POV) risk factors: surgery >30 min, age ≥3, history of POV or family, strabismus surgery. Postop vomiting affects up to 40-80% of pediatric patients without prophylaxis.' },
  { id: 167, section: 6, q: 'A caudal epidural in a 15-kg child for circumcision uses bupivacaine 0.25% at what typical volume?', options: ['0.25 mL/kg (Armitage low — sacral)', '0.5 mL/kg (mid-lumbar)', '1.0 mL/kg (high-thoracic — rarely needed)', '0.75 mL/kg for circumcision', '2 mL/kg'], answer: 0, rationale: 'Armitage formula: 0.5 mL/kg lumbosacral, 1 mL/kg thoracolumbar, 1.25 mL/kg mid-thoracic. For circumcision (sacral coverage) 0.5-0.75 mL/kg; low-volume US-guided techniques use 0.25 mL/kg.' },
  { id: 168, section: 6, q: 'The recommended initial fluid bolus for a hypovolemic pediatric patient is:', options: ['10 mL/kg crystalloid', '20 mL/kg crystalloid (LR or normal saline)', '40 mL/kg colloid', '5 mL/kg blood', '100 mL/kg over 1 hour'], answer: 1, rationale: 'PALS septic shock: 20 mL/kg balanced crystalloid bolus, reassess, repeat × 2-3 (up to 60 mL/kg in first hour).' },
  { id: 169, section: 6, q: 'Postextubation stridor in a child is managed first with:', options: ['Reintubation immediately', 'Humidified oxygen and racemic epinephrine nebulization + dexamethasone', 'Albuterol nebulization', 'Heliox alone', 'Lidocaine nebulizer'], answer: 1, rationale: 'Postextubation stridor (croup): humidified O₂, racemic epinephrine 0.5 mL of 2.25% in 3 mL saline (or L-epi), dexamethasone 0.25-0.5 mg/kg. Reintubate if failing.' },
  { id: 170, section: 6, q: 'The blood volume of a term neonate is approximately:', options: ['50 mL/kg', '60 mL/kg', '80 mL/kg', '90 mL/kg', '100 mL/kg'], answer: 3, rationale: 'Blood volume by age: preterm ~95 mL/kg, term neonate ~85-90 mL/kg, infant ~80, child ~75-80, adult male ~70, adult female ~65.' },

  // SECTION 7 — CARDIAC, NEURO, REGIONAL (171-200)
  { id: 171, section: 7, q: 'The MOST important determinant of myocardial oxygen DEMAND is:', options: ['Heart rate', 'Wall tension (afterload)', 'Contractility', 'Preload (ventricular volume)', 'All contribute but heart rate is typically most modifiable'], answer: 4, rationale: 'MVO₂ determinants: HR, wall tension, contractility. Tachycardia is doubly bad — ↑demand AND ↓supply (shortens diastolic coronary filling time). Target HR <70-80 with beta-blocker.' },
  { id: 172, section: 7, q: 'Coronary perfusion pressure of the LV is calculated as:', options: ['MAP – LVEDP (during diastole)', 'Systolic BP – RAP', 'MAP – PCWP', 'Diastolic BP – CVP', 'PCWP – LVEDP'], answer: 0, rationale: 'LV coronary perfusion occurs in DIASTOLE because intracavitary pressure exceeds aortic pressure in systole. CPP = aortic diastolic BP – LVEDP.' },
  { id: 173, section: 7, q: 'Anesthetic management of severe aortic stenosis requires:', options: ['Maintain sinus rhythm, normal-high SVR, normal HR (avoid tachycardia and bradycardia), adequate preload, avoid contractility depression', 'Tachycardia and low SVR', 'Spinal anesthesia preferred for spontaneous sympathectomy', 'Vasodilators and diuretics', 'Aggressive preload reduction'], answer: 0, rationale: 'Severe AS goals: "Full, slow, vasoconstricted, sinus" — adequate preload, slow normal HR (60-80), high SVR (phenylephrine), sinus rhythm. Avoid spinal/epidural; gentle GA preferred.' },
  { id: 174, section: 7, q: 'Anesthetic goals in severe mitral stenosis include:', options: ['Slow HR (avoid tachycardia — needs diastolic filling time), maintain sinus rhythm, avoid pulmonary HTN exacerbators (hypoxia, hypercarbia, acidosis), avoid hypovolemia and overload', 'Tachycardia and afterload reduction', 'Aggressive volume loading', 'Aggressive vasodilation', 'Pulmonary vasoconstriction'], answer: 0, rationale: 'MS: fixed obstruction at MV — LV filling depends on diastolic time. Avoid tachycardia. Avoid AFib loss of atrial kick. Avoid pulmonary hypertensive triggers. Cautious volume — narrow window.' },
  { id: 175, section: 7, q: 'In hypertrophic obstructive cardiomyopathy (HOCM), which intervention WORSENS LV outflow obstruction?', options: ['Phenylephrine (raises SVR — improves)', 'Beta-blocker (reduces contractility — improves)', 'Volume loading (improves preload, ↓obstruction)', 'Nitroglycerin or vasodilators (reduces preload/afterload — worsens)', 'Slowing HR with esmolol (improves)'], answer: 3, rationale: 'HOCM obstruction worsens with: ↓preload (vasodilators, hypovolemia), ↓afterload, ↑contractility. Improves with: volume, phenylephrine, beta-blockade, slow HR. Avoid inotropes and vasodilators.' },
  { id: 176, section: 7, q: 'Anesthetic induction in cardiac tamponade should preserve:', options: ['Fast, full, tight: maintain HR, preload, contractility, and SVR — ketamine + etomidate preferred', 'Bradycardia and afterload reduction', 'Aggressive volume restriction', 'Deep general anesthesia with high-dose propofol', 'Vasodilator-based induction'], answer: 0, rationale: 'Tamponade: fixed stroke volume — CO depends on HR. Goals: "fast, full, tight" — preserve preload, contractility, HR, SVR. Ketamine ideal (preserves SVR).' },
  { id: 177, section: 7, q: 'The target ACT for full heparinization before cardiopulmonary bypass is typically:', options: ['>200 sec', '>300 sec', '>400-480 sec', '>100 sec', 'Any ACT > baseline'], answer: 2, rationale: 'CPB requires ACT >400-480 sec for safe extracorporeal circulation. Initial heparin: 300-400 U/kg. Heparin resistance (AT III deficiency) — give AT III concentrate or FFP.' },
  { id: 178, section: 7, q: 'During cardiopulmonary bypass, MAP is generally targeted at:', options: ['20-30 mmHg', '30-50 mmHg (debated — higher 70-80 in high-risk for stroke/AKI)', '100-120 mmHg', 'Variable, not relevant', 'Whatever the surgeon requests'], answer: 1, rationale: 'Traditional CPB MAP target 50-65; recent evidence supports higher MAP 70-90 in elderly, hypertensive, atherosclerotic patients for cerebral/renal protection.' },
  { id: 179, section: 7, q: 'All of the following decrease intracranial pressure EXCEPT:', options: ['Hyperventilation to PaCO₂ 30-35 mmHg', 'Mannitol 0.5 g/kg', 'Hypertonic saline (3%)', 'Elevating head of bed 30°', 'Ketamine'], answer: 4, rationale: 'Ketamine historically thought to raise ICP — recent evidence shows minimal change when used with other anesthetics and controlled ventilation. Not used as a clinical ICP-lowering agent.' },
  { id: 180, section: 7, q: 'Cerebral blood flow (CBF) responds to PaCO₂ by approximately:', options: ['1 mL/100g/min change per 1 mmHg change in PaCO₂, between 20-80 mmHg', 'No change with PaCO₂', 'Inversely with PaCO₂ only at extremes', 'Only relevant during sleep', 'Only relevant under anesthesia'], answer: 0, rationale: 'CBF–CO₂ reactivity: ~1-2 mL/100g/min per mmHg PaCO₂ between 20-80 mmHg. Normal CBF 50 mL/100g/min. Hyperventilation lowers CBF/ICP but causes ischemia at PaCO₂ <25.' },
  { id: 181, section: 7, q: 'Anterior spinal artery syndrome causes:', options: ['Loss of all sensation below the level', 'Loss of motor function and pain/temperature with preserved proprioception/vibration', 'Pure motor loss', 'Hemisensory loss only', 'Pure proprioceptive loss'], answer: 1, rationale: 'Anterior spinal artery supplies anterior 2/3 of cord. Syndrome: motor loss + pain/temp loss with preserved vibration/proprioception (dorsal columns supplied by posterior spinal arteries).' },
  { id: 182, section: 7, q: 'During spine surgery with motor-evoked potential monitoring, which anesthetic technique is preferred?', options: ['High-dose volatile anesthetic (sevoflurane 1.5 MAC)', 'Total IV anesthesia (propofol + remifentanil) with minimal NMB', 'High-dose opioid + N₂O', 'Ketamine + N₂O', 'Volatile + nitrous oxide'], answer: 1, rationale: 'Volatile agents (>0.5 MAC), N₂O, benzodiazepines, and NMBs suppress MEPs. TIVA (propofol + opioid ± ketamine adjunct) is standard for MEP/SSEP monitoring.' },
  { id: 183, section: 7, q: 'The most concerning complication of the sitting position for craniotomy is:', options: ['Hypotension', 'Venous air embolism (VAE) — detected by TEE or precordial Doppler', 'Pneumocephalus', 'Nerve palsies', 'Pressure injuries'], answer: 1, rationale: 'Sitting position: VAE risk 25-45%. Detection: precordial Doppler (mill-wheel murmur), TEE (gold standard), drop in ETCO₂, rise in ET N₂. Treatment: flood field with saline, head-down, aspirate from CVL, 100% O₂.' },
  { id: 184, section: 7, q: 'During carotid endarterectomy with cross-clamping, cerebral monitoring includes all EXCEPT:', options: ['EEG', 'SSEPs', 'Stump pressure measurement', 'Awake monitoring (regional anesthesia)', 'Pulse pressure variation'], answer: 4, rationale: 'CEA cerebral monitoring: EEG, SSEPs, transcranial Doppler, stump pressure (>50 mmHg threshold), NIRS, awake neuro exam (gold standard with cervical plexus block). Pulse pressure variation is a fluid-responsiveness monitor.' },
  { id: 185, section: 7, q: 'Anesthetic management of an unsecured intracranial aneurysm before clipping prioritizes:', options: ['Avoid hypertension at induction and intubation — smooth induction with adequate analgesia, blunted DL response', 'Permissive hypertension to maintain CPP', 'Hyperventilation to PaCO₂ < 25', 'Profound hypotension throughout', 'Routine use of nitroprusside'], answer: 0, rationale: 'Unsecured aneurysm: AVOID transmural pressure spikes — smooth induction, deep anesthesia for laryngoscopy (lidocaine, opioids, esmolol). Euvolemia and normocarbia.' },
  { id: 186, section: 7, q: 'The "corner pocket" in supraclavicular brachial plexus block refers to:', options: ['The intersection of the first rib and the subclavian artery, where local anesthetic deposition gives the most reliable block', 'The interscalene groove', 'The axillary fossa', 'Below the clavicle near the brachial artery', 'The cubital fossa'], answer: 0, rationale: 'Supraclavicular "corner pocket" = junction of first rib and lateral border of subclavian artery — single-injection deposit here reliably anesthetizes the inferior trunk (often missed elsewhere).' },
  { id: 187, section: 7, q: 'A femoral nerve block covers:', options: ['Anterior thigh, knee (with quadriceps), and medial leg/foot via saphenous branch', 'Posterior thigh only', 'Plantar foot only', 'Entire lower limb', 'Lateral thigh only'], answer: 0, rationale: 'Femoral nerve (L2-L4): anterior thigh (cutaneous), quadriceps motor, knee joint, saphenous nerve → medial leg/foot. Combined with sciatic for full lower extremity surgery.' },
  { id: 188, section: 7, q: 'A transversus abdominis plane (TAP) block provides analgesia for:', options: ['Visceral abdominal pain', 'Somatic (parietal) pain from T7-L1 dermatomes of the anterior abdominal wall', 'Pelvic floor only', 'Subcutaneous thoracic wall only', 'Bladder distension'], answer: 1, rationale: 'TAP block deposits LA between internal oblique and transversus abdominis, blocking T7-L1 somatic afferents. Covers the abdominal WALL (incisional pain) but NOT visceral pain.' },
  { id: 189, section: 7, q: 'Per ASRA guidelines, deep blocks (lumbar plexus, paravertebral) follow the same anticoagulation guidelines as:', options: ['Peripheral blocks (more liberal)', 'Neuraxial anesthesia (strict)', 'Topical anesthesia', 'No restrictions', 'Only for therapeutic LMWH'], answer: 1, rationale: 'ASRA: Deep, non-compressible blocks (lumbar plexus/psoas, paravertebral, lumbar sympathetic, celiac plexus) follow neuraxial guidelines because of hematoma risk in non-compressible space.' },
  { id: 190, section: 7, q: 'Ultrasound guidance for peripheral nerve blocks has demonstrated which improvement over nerve stimulator?', options: ['Reduced incidence of LAST and decreased total LA dose required', 'Faster onset of block (variable evidence)', 'Lower failure rate (variable)', 'All of the above', 'No improvement'], answer: 3, rationale: 'Meta-analyses: US guidance reduces LA dose, lowers LAST incidence, may speed onset and reduce failures, fewer needle passes. Does not reliably reduce nerve injury vs nerve stim.' },
  { id: 191, section: 7, q: 'Intra-aortic balloon pump (IABP) inflation and deflation are timed to:', options: ['Inflate at end-diastole, deflate at peak systole', 'Inflate at the dicrotic notch (onset of diastole), deflate just before systole', 'Inflate continuously', 'Triggered by ECG R wave only without diastolic timing', 'Random pneumatic cycling'], answer: 1, rationale: 'IABP: inflates at the dicrotic notch (aortic valve closure → diastole) → augments coronary perfusion. Deflates just before systole → reduces afterload (↓LV work, ↑CO).' },
  { id: 192, section: 7, q: 'The most common reason for failed spinal anesthesia for cesarean delivery is:', options: ['Inadequate dose', 'Cephalad spread limited by pregnancy-related epidural compression', 'Patient movement during injection', 'Defective LA', 'All can contribute, with inadequate dose / inadequate density most common'], answer: 4, rationale: 'Cesarean spinal failure: dose too low, faulty technique (false-positive CSF return), too-rapid sit-up before block sets. Inadequate dose/density is most common overall.' },
  { id: 193, section: 7, q: 'Compared to adults, the MAC of sevoflurane in a 6-month-old is:', options: ['Lower', 'Higher (~3.2%)', 'Identical', 'Inversely related to body weight', 'Not measurable'], answer: 1, rationale: 'MAC peaks at age 1-6 months (sevoflurane ~3.2-3.3%) then decreases with age. Neonates have lower MAC than infants. Volatile uptake is faster in children (lower FRC, higher CO/alveolar ventilation).' },
  { id: 194, section: 7, q: 'During off-pump CABG, displacement of the heart for distal anastomoses commonly produces:', options: ['Severe hypotension and arrhythmia due to RV/LV obstruction or torsion', 'Hypertension', 'Improved cardiac output', 'Bradycardia only', 'No significant hemodynamic change'], answer: 0, rationale: 'Off-pump (OPCAB) cardiac displacement → impaired filling, ventricular obstruction, MR, arrhythmia. Management: anticipate, fluid loading, vasopressor, Trendelenburg, TEE essential.' },
  { id: 195, section: 7, q: 'At 1 MAC of isoflurane, cerebral blood flow and cerebral metabolic rate change:', options: ['Both increase (uncoupling)', 'Both decrease', 'CBF increases, CMRO₂ decreases (uncoupling)', 'No change', 'CBF decreases, CMRO₂ increases'], answer: 2, rationale: 'Volatile anesthetics uncouple CBF and CMRO₂: cerebral vasodilation increases CBF while metabolic demand decreases — "luxury perfusion." Effect is dose-dependent.' },
  { id: 196, section: 7, q: 'Within the first 6 weeks postpartum, pregnancy-associated airway changes (edema, vascular engorgement):', options: ['Resolve within 24 hours of delivery', 'Persist and may worsen with preeclampsia or fluid overload', 'Resolve only with diuresis', 'Never affect anesthetic management', 'Affect only smokers'], answer: 1, rationale: 'Pregnancy airway changes take several weeks to resolve and may worsen with preeclampsia (capillary leak), fluid loading, prolonged pushing. Postpartum airway management still requires pregnancy-level precautions for at least 4-6 weeks.' },
  { id: 197, section: 7, q: 'Atropine pretreatment before pediatric RSI with succinylcholine is recommended primarily to prevent:', options: ['Hyperkalemia', 'Bradycardia (especially with second dose or in infants <1 year)', 'Anaphylaxis', 'Masseter spasm', 'Postoperative nausea'], answer: 1, rationale: 'Succinylcholine in children causes vagally mediated bradycardia, particularly in infants <1 year and with repeat dosing. Atropine 0.02 mg/kg IV (minimum 0.1 mg) pretreats.' },
  { id: 198, section: 7, q: 'Acute spinal cord injury at C5 causes which immediate hemodynamic finding?', options: ['Hypertension and tachycardia', 'Hypotension and bradycardia (neurogenic shock from loss of sympathetic outflow)', 'Hypertension and bradycardia', 'Hypotension and tachycardia', 'Normal hemodynamics'], answer: 1, rationale: 'Neurogenic shock (high SCI above T6): loss of sympathetic tone → hypotension + bradycardia (unopposed vagal). Distinguish from hypovolemic shock (tachycardia). Treat: fluids + NE, atropine for bradycardia.' },
  { id: 199, section: 7, q: 'TEE-derived ejection fraction estimation in the transgastric mid-papillary view assesses:', options: ['Right ventricular function only', 'Left ventricular function and regional wall motion in all coronary distributions', 'Aortic valve only', 'Pulmonary vein flow', 'Tricuspid valve only'], answer: 1, rationale: 'TG-MID SAX: best single view for LV global function, EF, regional wall motion in all 3 coronary territories, and papillary muscle anatomy.' },
  { id: 200, section: 7, q: 'For an emergent stat cesarean delivery in a parturient without a working epidural and without IV access, the fastest induction of anesthesia is:', options: ['Spinal anesthesia after IV placement', 'Inhalational induction with sevoflurane, then IV/intubation (rare scenario)', 'GA with rapid IV placement, preoxygenation, RSI with propofol/sux', 'Pudendal block', 'Local infiltration only'], answer: 2, rationale: 'Stat C/S no working epidural: GA with RSI (preoxygenate, propofol + sux, cricoid, intubate, low-dose volatile until cord clamped). Spinal possible if time allows (~5-7 min).' },

  // SECTION 8 — SPECIAL PROBLEMS (201-250)
  { id: 201, section: 8, q: 'The earliest and most sensitive clinical sign of malignant hyperthermia (MH) is:', options: ['Hyperthermia', 'Masseter muscle rigidity', 'Unexplained rise in end-tidal CO₂ despite adequate ventilation', 'Tachycardia', 'Mottled skin'], answer: 2, rationale: 'Rising ETCO₂ unresponsive to increased ventilation is the EARLIEST sensitive sign of MH — reflecting hypermetabolism. Hyperthermia is a LATE sign (can be 1-2°C/hr rise).' },
  { id: 202, section: 8, q: 'MH-triggering agents include:', options: ['All volatile anesthetics and succinylcholine', 'Propofol and remifentanil', 'Local anesthetics', 'Benzodiazepines and opioids', 'Nitrous oxide'], answer: 0, rationale: 'MH triggers: all potent halogenated volatiles (sevo, des, iso) AND succinylcholine. SAFE: N₂O, propofol, etomidate, ketamine, opioids, benzodiazepines, all NDNMBs, all local anesthetics.' },
  { id: 203, section: 8, q: 'Initial dantrolene dose for active MH crisis is:', options: ['1 mg/kg IV', '2.5 mg/kg IV bolus, repeat every 5-10 min until resolved (up to 10+ mg/kg)', 'Oral 25 mg', '10 mg/kg IM', '0.5 mg/kg over 1 hour'], answer: 1, rationale: 'Dantrolene: 2.5 mg/kg IV bolus, repeat q5-10 min until signs resolve (commonly need 5-10+ mg/kg). After resolution: 1 mg/kg q6h × 24-48 h to prevent recurrence. MHAUS hotline: 1-800-644-9737.' },
  { id: 204, section: 8, q: 'The most common cause of anaphylaxis during anesthesia is:', options: ['Opioids', 'Neuromuscular blocking agents (rocuronium, succinylcholine)', 'Volatile anesthetics', 'Local anesthetics', 'Propofol'], answer: 1, rationale: 'Intraoperative anaphylaxis: NMBs ~60% (rocuronium and sux most common), latex 15-20% (declining), antibiotics, chlorhexidine. Cross-reactivity among NMBs via quaternary ammonium epitopes.' },
  { id: 205, section: 8, q: 'First-line treatment of severe intraoperative anaphylaxis is:', options: ['Diphenhydramine 50 mg IV', 'Hydrocortisone 100 mg IV', 'Epinephrine 10-100 mcg IV bolus (titrate to effect) + IV fluids', 'Albuterol nebulizer', 'Methylene blue 1 mg/kg'], answer: 2, rationale: 'Anaphylaxis: epinephrine FIRST and FOREMOST. IV bolus 10-100 mcg, escalating to mg doses if needed; infusion if persistent. IV fluids (large volumes). Adjuncts: H1/H2 blockers, corticosteroids.' },
  { id: 206, section: 8, q: 'Serum tryptase confirming anaphylaxis should be drawn at:', options: ['Immediately after reaction and at 1-2 h (peak); compare with baseline (24+ h after) if possible', 'Only at 24 hours', 'Only at presentation', 'Annually', 'Tryptase is not useful'], answer: 0, rationale: 'Mast cell tryptase peaks 30 min – 2 h after anaphylaxis, returns to baseline 12-24 h. Draw immediately and at 1-2 hours. Skin testing 4-6 weeks post-event to identify trigger.' },
  { id: 207, section: 8, q: 'Permissive hypotension in trauma resuscitation (without TBI) targets a systolic BP of approximately:', options: ['120 mmHg', '100 mmHg', '80-90 mmHg until hemorrhage controlled', '60 mmHg', 'Higher than baseline'], answer: 2, rationale: 'Permissive hypotension: target SBP 80-90 (MAP ~65) in penetrating trauma without TBI until surgical hemorrhage control — avoids exacerbating ongoing bleeding.' },
  { id: 208, section: 8, q: 'Succinylcholine should be avoided after major thermal injury starting:', options: ['Immediately', 'After 24 hours and until at least 12 months post-injury (and possibly longer)', 'After 1 week only', 'Only if burn > 50% TBSA', 'Only with concurrent infection'], answer: 1, rationale: 'Sux is SAFE in the first 24 h. Upregulation of extrajunctional ACh receptors begins ~24-48 h, peaks 1-6 weeks, persists until full healing (~1 year). Risk: massive K⁺ release → cardiac arrest.' },
  { id: 209, section: 8, q: 'The Parkland formula for burn fluid resuscitation in the first 24 hours uses:', options: ['2 mL/kg/% TBSA crystalloid', '4 mL/kg/% TBSA LR, half in first 8 h, remainder over next 16 h', '1 mL/kg/% TBSA colloid', '10 mL/kg/% TBSA LR', 'No fluid resuscitation'], answer: 1, rationale: 'Parkland: 4 mL × kg × %TBSA LR over 24 h (50% in first 8 h from time of burn). Titrate to urine output 0.5-1 mL/kg/h.' },
  { id: 210, section: 8, q: 'Elderly patients (>65) typically require what change in drug dosing?', options: ['No change', 'Increased doses due to higher Vd', 'Decreased induction doses (e.g., propofol by 25-50%) and slower onset/offset', 'Doubled doses', 'Variable, but typically higher'], answer: 2, rationale: 'Aging: ↓lean mass, ↑fat, ↓CO, ↓renal/hepatic clearance, ↓protein binding. MAC decreases ~6%/decade after 40. Reduce propofol, opioids, midazolam by 25-50%. Postop delirium risk — avoid benzos.' },
  { id: 211, section: 8, q: 'Postoperative delirium in the elderly is reduced by all EXCEPT:', options: ['Avoidance of benzodiazepines and anticholinergics', 'Dexmedetomidine infusion', 'Multimodal opioid-sparing analgesia', 'Routine use of haloperidol prophylaxis', 'Early mobilization, reorientation, sleep hygiene'], answer: 3, rationale: 'Delirium prevention: avoid Beers list drugs, dexmedetomidine for ICU sedation, multimodal analgesia, processed EEG monitoring (avoid burst suppression), early mobilization. Routine haloperidol prophylaxis has NOT consistently shown benefit.' },
  { id: 212, section: 8, q: 'Dosing of induction agents in morbid obesity generally uses:', options: ['Total body weight for all', 'Lean body weight or ideal body weight (e.g., propofol induction by LBW; maintenance by TBW)', 'Always actual body weight', 'Always ideal body weight', 'Variable, no general rule'], answer: 1, rationale: 'Obese dosing: induction propofol — LBW; fentanyl — LBW; sux — TBW (↑ pseudocholinesterase); rocuronium — IBW; sugammadex — TBW; volatile MAC unchanged.' },
  { id: 213, section: 8, q: 'Patients with obstructive sleep apnea are at greatest perioperative risk for:', options: ['Difficult intubation, postoperative respiratory depression, and pulmonary complications', 'Cardiac arrest only', 'Wound infection', 'Anaphylaxis', 'Hypertensive crisis'], answer: 0, rationale: 'OSA risks: difficult mask ventilation and intubation, opioid-induced respiratory depression with collapse, atelectasis, pulmonary HTN/RV failure. STOP-BANG screening preop. Minimize opioids.' },
  { id: 214, section: 8, q: 'The WHO analgesic ladder for chronic pain places which agent at step 1?', options: ['Strong opioids (morphine)', 'Non-opioids (acetaminophen, NSAIDs) ± adjuvants', 'Weak opioids (codeine, tramadol)', 'Methadone', 'Ketamine'], answer: 1, rationale: 'WHO ladder: 1) Non-opioid ± adjuvant; 2) Add weak opioid; 3) Strong opioid. Modern multimodal approach targets multiple pathways for opioid sparing.' },
  { id: 215, section: 8, q: 'Gabapentinoids (gabapentin, pregabalin) act primarily by:', options: ['GABA receptor agonism', 'Binding the α2δ subunit of voltage-gated calcium channels in the CNS, reducing presynaptic glutamate release', 'NMDA antagonism', 'Mu opioid agonism', 'Serotonin reuptake inhibition'], answer: 1, rationale: 'Gabapentin/pregabalin bind α2δ-1 subunit of VGCCs → ↓Ca²⁺ influx → ↓neurotransmitter release. Useful for neuropathic pain and perioperative multimodal analgesia.' },
  { id: 216, section: 8, q: 'Standard adult IV morphine PCA settings include:', options: ['No basal, 1 mg demand, 6-10 min lockout, 4-hour limit', '10 mg basal continuous, 5 mg demand', 'Demand-only with 1 min lockout', 'Continuous infusion only, no demand', 'Variable, but basal infusion always required'], answer: 0, rationale: 'Adult morphine IVPCA: demand 1 mg, lockout 6-10 min, 4-h limit ~20-30 mg. Basal infusions increase respiratory depression risk in opioid-naive patients — avoid.' },
  { id: 217, section: 8, q: 'Multimodal analgesia after major abdominal surgery typically includes:', options: ['Opioid only', 'Acetaminophen + NSAID/COX-2 + opioid + regional (epidural or TAP) + adjuvants (ketamine, gabapentinoid, dexmedetomidine) as appropriate', 'Ketamine infusion only', 'Acupuncture only', 'Lidocaine patches only'], answer: 1, rationale: 'ERAS multimodal analgesia: scheduled APAP + NSAID (ketorolac), epidural or TAP block, low-dose ketamine, gabapentinoid (pre-induction), dexamethasone, dexmedetomidine, magnesium, opioid-sparing.' },
  { id: 218, section: 8, q: 'The FLACC scale for pediatric pain assessment evaluates:', options: ['Face, Legs, Activity, Cry, Consolability', 'Faint, Lethargic, Anxious, Comfortable, Calm', 'Fast, Long, Acute, Chronic, Constant', 'Fever, Lethargy, Appetite, Crying, Constipation', 'Frontal, Lateral, Anterior, Caudal, Cervical'], answer: 0, rationale: 'FLACC pain scale (children 2 months–7 years): Face, Legs, Activity, Cry, Consolability — each 0-2, total 0-10.' },
  { id: 219, section: 8, q: 'After episode of intraoperative awareness, the most important intervention is:', options: ['Reassure the patient that this never happens again', 'Acknowledge, apologize, listen, screen for PTSD symptoms, refer for mental health support, root-cause analysis', 'Charge a fee for additional anesthesia', 'Avoid any future surgery', 'Ignore the report'], answer: 1, rationale: 'Awareness with recall is psychologically traumatic — up to 50% develop PTSD. Approach: acknowledge, validate, apologize, structured interview, mental health referral, identify cause, document.' },
  { id: 220, section: 8, q: 'TURP syndrome from hypotonic irrigation absorption presents with:', options: ['Hyperglycemia and hyponatremia', 'Dilutional hyponatremia, fluid overload, cerebral edema, hemolysis (depending on irrigant)', 'Hypernatremia and dehydration', 'Acute renal failure only', 'Hyperkalemia'], answer: 1, rationale: 'TURP syndrome: absorption of hypotonic irrigation (glycine 1.5%, sorbitol, mannitol) through prostatic venous sinuses → dilutional hyponatremia, fluid overload, visual disturbances, seizures, cerebral edema.' },
  { id: 221, section: 8, q: 'Patients at highest risk for latex allergy include all EXCEPT:', options: ['Healthcare workers', 'Patients with spina bifida or urogenital anomalies (repeated catheterization)', 'Patients with multiple surgeries from infancy', 'Patients with avocado/banana/kiwi cross-reactivity', 'Smokers with COPD'], answer: 4, rationale: 'Latex allergy risk: healthcare workers, spina bifida, repeated GU/GI surgery from infancy, atopy, cross-reactive foods (avocado, banana, kiwi, chestnut — "latex-fruit syndrome"). Smoking/COPD is NOT a risk factor.' },
  { id: 222, section: 8, q: 'Stress-induced hyperglycemia perioperatively should target a blood glucose of approximately:', options: ['80-110 mg/dL (strict — high hypoglycemia risk)', '140-180 mg/dL (moderate — NICE-SUGAR/SCCM)', '>200 mg/dL', '<70 mg/dL', 'No target'], answer: 1, rationale: 'NICE-SUGAR (2009): intensive glucose control (81-108) increased mortality vs conventional (<180). Current SCCM/ADA recommendation: perioperative glucose 140-180 mg/dL.' },
  { id: 223, section: 8, q: 'Thyroid storm during surgery is treated with all EXCEPT:', options: ['IV beta-blocker (esmolol or propranolol)', 'Propylthiouracil (PTU) or methimazole', 'Aspirin to control fever', 'Iodine (Lugol\'s solution) at least 1 h after PTU/methimazole', 'Hydrocortisone'], answer: 2, rationale: 'Thyroid storm: beta-blockade, PTU/methimazole, iodine (after antithyroids), corticosteroids, cooling (acetaminophen — NOT aspirin, which displaces T4 from binding proteins and worsens). Treat trigger.' },
  { id: 224, section: 8, q: 'Preoperative preparation of pheochromocytoma requires:', options: ['Beta-blockade before alpha-blockade', 'Alpha-blockade (phenoxybenzamine or doxazosin) for 10-14 days before adding beta-blocker as needed', 'No preparation needed', 'Diuretics and ACE inhibitors', 'Surgery without medical optimization'], answer: 1, rationale: 'Pheo: ALPHA-blockade FIRST (phenoxybenzamine 10-40 mg BID or doxazosin) for 10-14 days, then β-blockade ONLY after alpha (unopposed α with β-block first → hypertensive crisis).' },
  { id: 225, section: 8, q: 'Intraoperative hypertensive crisis during pheochromocytoma manipulation is best treated with:', options: ['Phenylephrine', 'Esmolol alone', 'Nitroprusside, nicardipine, or phentolamine (short-acting agents)', 'Norepinephrine', 'Long-acting beta-blockers'], answer: 2, rationale: 'Pheo crisis: short-acting agents — nitroprusside, nicardipine (preferred at many centers), phentolamine (classic α-blocker). After tumor ligation — hypotension common → fluids, NE, vasopressin.' },
  { id: 226, section: 8, q: 'Myasthenia gravis patients show abnormal sensitivity to which NMB class?', options: ['Resistance to succinylcholine, sensitivity to nondepolarizers', 'Resistance to all NMBs', 'Sensitivity to succinylcholine only', 'Sensitivity to nondepolarizers; variable response to succinylcholine (often resistance)', 'Normal response'], answer: 3, rationale: 'MG (anti-AChR antibodies, fewer functional receptors): VERY SENSITIVE to nondepolarizers (use ~10-50% dose, TOF monitoring); RESISTANT to succinylcholine (need higher dose).' },
  { id: 227, section: 8, q: 'Perioperative management of sickle cell disease aims to prevent sickling by avoiding:', options: ['Hypoxia, hypothermia, acidosis, dehydration, stasis, infection', 'Hypertension only', 'Hyperglycemia only', 'Hyperventilation only', 'Spinal anesthesia'], answer: 0, rationale: 'Sickling triggers: hypoxia, hypothermia, hypovolemia/dehydration, acidosis, hypotension, stasis, infection. Prevent: aggressive O₂, warming, balanced fluids, normothermia, ± exchange transfusion (HbS <30%).' },
  { id: 228, section: 8, q: 'In chronic kidney disease (CKD), which drug should be AVOIDED for prolonged paralysis risk?', options: ['Cisatracurium', 'Vecuronium', 'Atracurium', 'Succinylcholine', 'Rocuronium'], answer: 1, rationale: 'Vecuronium is primarily hepatic/biliary and renal-cleared → dramatically prolonged in CKD. Pancuronium similarly. Prefer cisatracurium (Hofmann elimination — organ-independent).' },
  { id: 229, section: 8, q: 'Pseudocholinesterase is synthesized by the liver. In severe liver failure, succinylcholine effect is:', options: ['Markedly shortened', 'Normal', 'Prolonged due to reduced pseudocholinesterase levels (clinically modest unless severe)', 'Reversed', 'Not metabolized at all'], answer: 2, rationale: 'Pseudocholinesterase is hepatic-synthesized. Decreased in severe liver disease → succinylcholine duration prolonged but usually <30 min unless atypical enzyme or extreme deficiency.' },
  { id: 230, section: 8, q: 'Coagulopathy in advanced liver disease results from:', options: ['Decreased synthesis of all coagulation factors EXCEPT VIII and vWF; also decreased anticoagulants (protein C/S, AT) — balanced "rebalanced" coagulation', 'Excess platelet activity', 'Pure thrombocytosis', 'Hyperfibrinolysis only', 'No coagulopathy'], answer: 0, rationale: 'Liver synthesizes most coag factors (except VIII, vWF). Also synthesizes anticoagulants (protein C/S, AT III). "Rebalanced hemostasis" — INR prolonged but thrombosis risk preserved. TEG/ROTEM more useful than INR.' },
  { id: 231, section: 8, q: 'The earliest perioperative benefit of smoking cessation occurs within:', options: ['24 hours: COHb falls, oxygen delivery improves', '1 week: airway irritability decreases', '4 weeks: pulmonary complications decrease', '8+ weeks: marked decrease in pulm complications', 'Smoking cessation has no perioperative benefit'], answer: 0, rationale: '"No benefit in stopping right before" is a myth — even 24-h cessation improves oxygen delivery (COHb halves). Optimal cessation is ≥8 weeks before surgery for major pulmonary benefits.' },
  { id: 232, section: 8, q: 'Diabetic gastroparesis affects anesthetic management primarily by:', options: ['Increasing risk of perioperative aspiration — full-stomach precautions', 'Decreasing protein binding of drugs', 'Reducing MAC', 'Causing hyperthermia', 'Increasing volume of distribution'], answer: 0, rationale: 'Diabetic autonomic neuropathy: gastroparesis → full stomach risk → RSI even after fasting. Other DM concerns: difficult airway (stiff joint syndrome), CAD, nephropathy, neuropathy.' },
  { id: 233, section: 8, q: 'All of the following are contraindicated in pheochromocytoma EXCEPT:', options: ['Ephedrine', 'Glucagon', 'Droperidol', 'Metoclopramide', 'Phenylephrine (cautious for refractory hypotension only)'], answer: 4, rationale: 'AVOID in pheo: indirect sympathomimetics (ephedrine, dopamine), glucagon (stimulates catecholamine release), metoclopramide and droperidol (dopamine antagonism → catecholamine release). Phenylephrine acceptable after alpha blockade.' },
  { id: 234, section: 8, q: 'Anti-platelet management before elective non-cardiac surgery in a patient with recent (3-month) drug-eluting stent should:', options: ['Stop ASA and P2Y12 5 days before', 'Delay surgery if possible until DAPT complete (≥6-12 months); continue ASA throughout', 'Bridge with heparin and stop all antiplatelets', 'Stop just P2Y12 the morning of surgery', 'Stop both 1 day before'], answer: 1, rationale: 'Recent DES (within 6 months): delay elective surgery until DAPT complete. For urgent surgery: continue ASA, hold P2Y12 (clopidogrel 5-7 d). Heparin bridging is NOT helpful (platelet-mediated).' },
  { id: 235, section: 8, q: 'A patient\'s DNR order in the perioperative period:', options: ['Is automatically suspended for surgery', 'Must be addressed (required reconsideration) with the patient/surrogate to determine which interventions are wanted intraoperatively', 'Forbids any resuscitative action regardless', 'Permits intubation only', 'Applies only after surgery'], answer: 1, rationale: 'ASA Ethical Guidelines: DNR orders should NOT be automatically suspended in the OR — require reconsideration with the patient/surrogate to determine scope of acceptable interventions.' },
  { id: 236, section: 8, q: 'Application of a magnet to a permanent pacemaker generally causes:', options: ['Inhibition of pacing', 'Asynchronous (DOO or VOO) pacing at a manufacturer-specific rate', 'Defibrillation', 'Reprogramming', 'Disabling the device'], answer: 1, rationale: 'Magnet over pacemaker → asynchronous mode (DOO or VOO) at programmed magnet rate (usually 85-100 bpm). Magnet over ICD → suspends arrhythmia detection/therapy (does NOT change pacing mode).' },
  { id: 237, section: 8, q: 'Mild perioperative hypothermia (~1°C below normal) is associated with all EXCEPT:', options: ['Increased wound infections', 'Coagulopathy (platelet dysfunction, slowed enzymatic cascade)', 'Prolonged drug effects (anesthetics, NMBs)', 'Decreased postoperative pain', 'Postoperative shivering and patient discomfort'], answer: 3, rationale: 'Inadvertent perioperative hypothermia: wound infection, coagulopathy, prolonged drug effects, shivering (↑O₂ consumption 400%). INCREASES (not decreases) postop pain.' },
  { id: 238, section: 8, q: 'After confirmed awareness with recall, the patient should be:', options: ['Re-anesthetized with same technique to demonstrate it works', 'Reassured that awareness never recurs', 'Counseled about the event, screened for PTSD, and root-cause analysis performed', 'Charged additional fees', 'Discharged immediately'], answer: 2, rationale: 'Post-awareness approach: acknowledge, validate, apologize, identify and explain cause, mental health referral (PTSD rates up to 50%), risk management consult, document, plan future anesthetics.' },
  { id: 239, section: 8, q: 'Chronic alcohol use affects MAC by:', options: ['Decreasing MAC (sensitization)', 'Increasing MAC for volatile anesthetics (cross-tolerance)', 'No change', 'Variable, but generally lower', 'Increasing MAC for opioids only'], answer: 1, rationale: 'Chronic ethanol use: upregulates GABA receptors, induces CYP2E1 → cross-tolerance to volatiles, benzodiazepines, opioids. Acute intoxication: REDUCED dose required (synergistic with anesthetics).' },
  { id: 240, section: 8, q: 'An opioid-tolerant patient on 200 MME/day requires which postoperative pain strategy?', options: ['Same opioid dose as opioid-naive', 'Maintain baseline opioid (often via PCA basal or scheduled), add multimodal non-opioids, regional anesthesia, ketamine, dexmedetomidine; expect higher total opioid requirement', 'Stop all opioids', 'Methadone only', 'Acetaminophen only'], answer: 1, rationale: 'Opioid-tolerant patient: maintain baseline opioids (avoid withdrawal), aggressive multimodal — regional, ketamine, dexmedetomidine, gabapentinoids, NSAIDs/APAP. Expect 30-100% above baseline for acute pain.' },
  { id: 241, section: 8, q: 'A patient on buprenorphine 16 mg/day for opioid use disorder requires surgery. Current best practice is:', options: ['Stop buprenorphine 24-72 h preop', 'Continue buprenorphine, manage pain with multimodal analgesia + full-agonist opioid (often higher doses needed)', 'Substitute methadone', 'Postpone surgery indefinitely', 'Use ketamine only'], answer: 1, rationale: 'Modern guidance: CONTINUE buprenorphine perioperatively. Stopping risks relapse. Buprenorphine has high mu affinity but partial activity — full agonist opioids still work at higher doses. Combine with regional, ketamine, multimodal.' },
  { id: 242, section: 8, q: 'Open-globe injury anesthesia traditionally avoids succinylcholine because of fear of:', options: ['Increased intraocular pressure causing extrusion of contents (limited modern evidence)', 'Hypotension', 'Myocardial depression', 'Arrhythmia only', 'Pseudocholinesterase deficiency'], answer: 0, rationale: 'Sux briefly increases IOP (~6-8 mmHg). Modern view: sux generally acceptable with full RSI. Rocuronium 1.2 mg/kg is acceptable alternative.' },
  { id: 243, section: 8, q: 'Hyperalgesia after high-dose remifentanil intraoperatively is mediated by:', options: ['Mu receptor downregulation only', 'NMDA receptor activation and other proalgesic mechanisms', 'Histamine release', 'Direct neurotoxicity', 'GABA inhibition'], answer: 1, rationale: 'Opioid-induced hyperalgesia (OIH), especially with remifentanil, involves NMDA receptor activation and descending facilitation. Mitigation: ketamine adjunct, magnesium, gradual remi taper, multimodal.' },
  { id: 244, section: 8, q: 'In severe accidental hypothermia (core temp <30°C) with cardiac arrest, ACLS modifications include:', options: ['Withhold drugs until temperature >30°C (medication metabolism unpredictable)', 'Increased epinephrine doses', 'Continue ACLS exactly as in normothermia', 'Open-chest massage routinely', 'Hyperventilate aggressively'], answer: 0, rationale: 'Severe hypothermia (<30°C): drugs accumulate (unpredictable metabolism); withhold/space ACLS medications until core >30°C. Defibrillation may be ineffective until rewarmed. "Not dead until warm and dead."' },
  { id: 245, section: 8, q: 'Emergency cricothyroidotomy in "cannot intubate, cannot oxygenate" situation is performed at:', options: ['Thyrohyoid membrane', 'Cricothyroid membrane between the thyroid and cricoid cartilages', 'Sternal notch', 'Through the thyroid isthmus', 'Trachea below the cricoid'], answer: 1, rationale: 'Cricothyroidotomy: cricothyroid membrane (between thyroid cartilage above, cricoid cartilage below) — palpable as a soft "V" below the laryngeal prominence. Preferred technique: scalpel-finger-bougie.' },
  { id: 246, section: 8, q: 'After uneventful intubation, EtCO₂ reads 0 mmHg. The most concerning possibility is:', options: ['Cardiac arrest or esophageal intubation', 'Hypothermia', 'Patient hyperventilation', 'Equipment monitoring delay', 'Both A: this dual question essentially asks identify and treat: confirm tube placement and pulse'], answer: 0, rationale: 'ZERO EtCO₂ after intubation: esophageal intubation, cardiac arrest, complete airway disconnect, capnograph failure. CONFIRM immediately. "No CO₂ = no chance."' },
  { id: 247, section: 8, q: 'A patient on MAOI inhibitors requires emergency surgery. Which agent should be avoided?', options: ['Meperidine and ephedrine (serotonin syndrome / hypertensive crisis)', 'Acetaminophen', 'Lidocaine', 'Volatile anesthetic', 'Rocuronium'], answer: 0, rationale: 'MAOIs: AVOID meperidine, tramadol, dextromethorphan (serotonin syndrome — fatal); avoid indirect sympathomimetics ephedrine, dopamine (excessive NE release → hypertensive crisis). SAFE: morphine, fentanyl (carefully), direct vasopressors.' },
  { id: 248, section: 8, q: 'After an episode of intraoperative dental injury, the standard initial response includes:', options: ['Document, locate the tooth/fragment (chest X-ray to rule out aspiration), refer to dentistry, disclose to patient', 'Ignore unless patient mentions it', 'Never document', 'Dispose of the fragment', 'Insurance only — no clinical action'], answer: 0, rationale: 'Dental injuries: most common anesthesia closed-claim malpractice event. After injury: locate fragment (CXR if missing — aspiration could be catastrophic), preserve, refer to dentist, document, disclose to patient.' },
  { id: 249, section: 8, q: 'For general anesthesia for cesarean delivery, the typical induction agent dose adjustment is:', options: ['Increased due to volume of distribution', 'Standard adult doses', 'Lower doses considered (less for placental transfer); rapid sequence with cricoid; minimize volatile until cord clamped', 'No need to minimize volatile', 'Avoid all induction agents'], answer: 2, rationale: 'Cesarean GA: RSI — propofol 2 mg/kg + sux 1.5 mg/kg + cricoid. Low-dose volatile (0.5 MAC) until cord clamped to minimize fetal exposure. After clamping: increase MAC + opioids.' },
  { id: 250, section: 8, q: 'The Bezold-Jarisch reflex in spinal anesthesia produces:', options: ['Hypertension and tachycardia', 'Bradycardia and hypotension triggered by venous return reduction sensing', 'Bronchospasm', 'Increased renal perfusion', 'Tachycardia and bronchodilation'], answer: 1, rationale: 'Bezold-Jarisch reflex: empty ventricle/under-filled LV stimulates vagal afferents → reflex bradycardia, hypotension, vasodilation. Seen in high spinal, hypovolemia, vasovagal. Treatment: IV fluids, ephedrine, atropine.' },

  // SECTION 9 — ORGAN-BASED & COEXISTING (251-301)
  { id: 251, section: 9, q: 'The single most important spirometric predictor of post-pneumonectomy pulmonary function is:', options: ['Total lung capacity (TLC)', 'FEV1 only', 'Predicted postoperative FEV1 (ppoFEV1) calculated using lung segments', 'Vital capacity', 'Inspiratory capacity'], answer: 2, rationale: 'ppoFEV1 = preop FEV1 × (1 – fraction of lung removed). ppoFEV1 >40% = generally safe; <30% = high risk. Cardiopulmonary exercise test (VO₂max) if borderline.' },
  { id: 252, section: 9, q: 'Severe intraoperative bronchospasm in an asthmatic is best managed initially by:', options: ['Deepening anesthesia (volatile bronchodilation), 100% O₂, inhaled beta-2 agonist via ETT (8-10 puffs)', 'Switching to TIVA', 'Intravenous lidocaine 1.5 mg/kg', 'IV epinephrine 1 mg push', 'Methylprednisolone'], answer: 0, rationale: 'Intraoperative bronchospasm: deepen anesthesia (sevo > iso > des), 100% O₂, albuterol 8-10 puffs through ETT, epinephrine (10-100 mcg IV) if severe, IV steroids (delayed effect). Avoid morphine, atracurium (histamine).' },
  { id: 253, section: 9, q: 'Mechanical ventilation in a COPD patient with hyperinflation and auto-PEEP should:', options: ['Use long inspiratory times with high TV', 'Use prolonged expiratory time (low I:E ratio, e.g., 1:3-1:5), allow permissive hypercapnia, low TV (6 mL/kg IBW)', 'Maintain high frequency (>20/min)', 'Use 100% O₂', 'Avoid PEEP entirely'], answer: 1, rationale: 'COPD ventilation: avoid air-trapping/auto-PEEP. Strategy: low rate (8-12), long expiratory time (I:E 1:3-1:5), low TV 6-8 mL/kg IBW, permissive hypercapnia. Disconnect briefly if severe gas-trapping → cardiovascular collapse.' },
  { id: 254, section: 9, q: 'In a patient with severe pulmonary hypertension, anesthetic goals include:', options: ['Avoid hypoxia, hypercarbia, acidosis (all worsen PVR), avoid N₂O, maintain RV preload, maintain coronary perfusion, use inhaled NO/prostacyclin if needed', 'High-dose volatile to vasodilate', 'Aggressive volume restriction', 'Beta-blockade to maximum tolerated', 'Permissive hypercapnia'], answer: 0, rationale: 'Pulmonary HTN: avoid PVR-raising factors (hypoxia, hypercarbia, acidosis, hypothermia, N₂O). Maintain RV function: preload optimization (cautious), maintain systemic BP for RV coronary supply. Inhaled NO 20-40 ppm.' },
  { id: 255, section: 9, q: 'A patient with EF 25% (heart failure with reduced EF) tolerates which induction agent best?', options: ['Propofol 2.5 mg/kg', 'Etomidate 0.3 mg/kg (preserves contractility, minimal vasodilation)', 'Thiopental 5 mg/kg', 'Midazolam 0.3 mg/kg + propofol 2 mg/kg', 'Ketamine 2 mg/kg'], answer: 1, rationale: 'Low EF: etomidate ideal — preserves hemodynamics. Ketamine useful if not catecholamine-depleted. Propofol: profound vasodilation/cardiac depression — slow titration or avoid. Avoid pancuronium (tachycardia).' },
  { id: 256, section: 9, q: 'In Wolff-Parkinson-White (WPW) syndrome with pre-excited atrial fibrillation, which drug is contraindicated?', options: ['Amiodarone', 'Adenosine, beta-blockers, calcium channel blockers, digoxin (all block AV node → preferential conduction down accessory pathway → 1:1 ventricular response → VF)', 'Procainamide', 'Esmolol-only', 'Lidocaine'], answer: 1, rationale: 'WPW + pre-excited AFib: AV nodal blockers → antegrade conduction down accessory pathway → rapid VR (>250 bpm) → degenerates to VF. Use procainamide, ibutilide, or DC cardioversion.' },
  { id: 257, section: 9, q: 'Acute kidney injury (AKI) by KDIGO criteria includes any of:', options: ['Cr rise ≥0.3 mg/dL in 48h, or 1.5× baseline in 7 days, or UO <0.5 mL/kg/h for 6+ hours', 'Cr rise ≥2 mg/dL only', 'Anuria only', 'BUN >100 only', 'Fluid overload only'], answer: 0, rationale: 'KDIGO AKI: Cr ≥0.3 mg/dL rise in 48 h OR ≥1.5× baseline in 7 d OR UO <0.5 mL/kg/h × 6 h. Staged 1-3 by severity.' },
  { id: 258, section: 9, q: 'Dialysis-dependent CKD patients should NOT receive which volume expander?', options: ['Normal saline (large volumes cause hyperchloremic acidosis and hyperkalemia)', '5% albumin', 'Lactated Ringer\'s (K+ 4 mEq/L) — concern is overstated; usually safe', 'Both A and the K+ in LR matter; minimize chloride', 'Crystalloids contraindicated'], answer: 3, rationale: 'ESRD volume management: avoid chloride-rich NS in large volumes (→ hyperchloremic acidosis → ↑K). LR\'s K (4 mEq/L) usually safe in small-moderate volumes. Minimize chloride load overall.' },
  { id: 259, section: 9, q: 'Child-Pugh class C cirrhosis is associated with perioperative mortality for major abdominal surgery of approximately:', options: ['1-5%', '10-15%', '30-50% or higher', '<1%', 'Same as healthy patients'], answer: 2, rationale: 'Child-Pugh: A (5-6 pts, mortality ~10%), B (7-9, ~30%), C (10-15, 75%+). MELD score: predicts 90-day mortality. >15 = contraindication for elective non-transplant surgery.' },
  { id: 260, section: 9, q: 'Stress-dose steroid coverage is INDICATED in which patient?', options: ['Patient on inhaled fluticasone only', 'Patient on prednisone 5 mg/day for <1 month', 'Patient on prednisone 20 mg/day for >3 weeks', 'Patient who stopped prednisone 6 months ago', 'Topical hydrocortisone only'], answer: 2, rationale: 'HPA suppression risk: prednisone ≥5 mg/d for ≥3 weeks (or equivalent). Coverage for major surgery: 100 mg hydrocortisone at induction + 50-100 mg q8h × 24-48h.' },
  { id: 261, section: 9, q: 'Which opioid is generally PREFERRED in patients with severe renal impairment?', options: ['Morphine', 'Meperidine', 'Codeine', 'Fentanyl or hydromorphone (fewer renally cleared active metabolites)', 'Oxycodone'], answer: 3, rationale: 'ESRD opioids: AVOID morphine (M6G accumulates), meperidine (normeperidine — seizures), codeine (unpredictable). PREFER fentanyl, hydromorphone, methadone, buprenorphine.' },
  { id: 262, section: 9, q: 'Diabetic ketoacidosis (DKA) intraoperatively presents with:', options: ['Hyperglycemia, anion-gap metabolic acidosis, ketonuria, dehydration', 'Hypoglycemia only', 'Respiratory alkalosis', 'Hypernatremia only', 'Asymptomatic'], answer: 0, rationale: 'DKA: glucose >250, AGMA (pH <7.3, HCO₃ <18), ketonuria/ketonemia. Treatment: IV insulin infusion (after volume + K⁺ check), aggressive fluid resuscitation, replace K⁺.' },
  { id: 263, section: 9, q: 'Hereditary spherocytosis patients undergoing splenectomy require:', options: ['Avoid all anesthesia', 'Pre- and postoperative vaccination against encapsulated organisms (pneumococcus, meningococcus, Hib)', 'Steroids only', 'Avoid volatiles only', 'RBC transfusion routinely'], answer: 1, rationale: 'Splenectomy preparation: vaccinate ≥2 weeks before elective surgery against Strep pneumoniae, N. meningitidis, H. influenzae type b. Risk of overwhelming post-splenectomy infection (OPSI).' },
  { id: 264, section: 9, q: 'Revised Cardiac Risk Index (RCRI) for perioperative MACE includes all EXCEPT:', options: ['High-risk surgery', 'Ischemic heart disease', 'Heart failure', 'Cerebrovascular disease', 'Hypertension stage 1'], answer: 4, rationale: 'RCRI (Lee Index) — 6 factors: 1) high-risk surgery, 2) IHD, 3) CHF, 4) CVD (TIA/stroke), 5) insulin-treated DM, 6) Cr >2 mg/dL. ≥2 factors → elevated risk. Mild HTN is NOT in RCRI.' },
  { id: 265, section: 9, q: 'Functional capacity <4 METs (e.g., cannot climb a flight of stairs) is associated with:', options: ['Lower perioperative cardiac risk', 'Higher perioperative cardiac risk and potential indication for further evaluation', 'No prognostic value', 'Lower mortality', 'Reduced anesthesia requirements'], answer: 1, rationale: 'Functional capacity in METs: 1=eating, 4=climbing stairs, 10=strenuous sports. <4 METs = poor functional capacity = increased cardiac risk. ACC/AHA algorithm: if MET <4 + elevated risk → consider noninvasive testing.' },
  { id: 266, section: 9, q: 'Parkinson disease patients should:', options: ['Have all medications stopped 24 h preop', 'Continue antiparkinsonian medications including dose on morning of surgery; avoid metoclopramide, droperidol, phenothiazines (worsen symptoms)', 'Stop only levodopa', 'Receive haloperidol prophylactically', 'Be given anticholinergics only'], answer: 1, rationale: 'Parkinson: continue carbidopa-levodopa (short half-life — withdrawal → severe rigidity, dysphagia, respiratory failure). Avoid D2 antagonists (metoclopramide, droperidol, phenothiazines). Safe antiemetics: ondansetron, dexamethasone.' },
  { id: 267, section: 9, q: 'Multiple sclerosis patients undergoing surgery should:', options: ['Avoid all neuraxial anesthesia (controversial — see explanation)', 'Be informed about possible exacerbation; maintain normothermia (hyperthermia exacerbates demyelination)', 'Receive steroids prophylactically', 'Avoid all volatile anesthetics', 'Receive interferon perioperatively'], answer: 1, rationale: 'MS: perioperative exacerbation risk (heat, stress, infection). HYPERTHERMIA worsens conduction block — keep normothermic (Uhthoff phenomenon). Neuraxial: not absolutely contraindicated; document discussion.' },
  { id: 268, section: 9, q: 'Carcinoid crisis triggered by tumor manipulation is best managed by:', options: ['Beta-blocker alone', 'Octreotide bolus (50-100 mcg) ± infusion, IV fluids, vasopressors as needed (avoid catecholamines that may worsen flushing)', 'Diphenhydramine', 'Steroids only', 'Calcium channel blocker'], answer: 1, rationale: 'Carcinoid crisis: octreotide bolus, fluids, careful vasopressors (catecholamines may trigger more mediator release → phenylephrine preferred). Pre-op octreotide infusion essential. Avoid histamine releasers (morphine, sux).' },
  { id: 269, section: 9, q: 'A patient with Mobitz type II second-degree AV block typically requires:', options: ['No intervention', 'Permanent pacemaker before elective surgery, or temporary perioperatively', 'Atropine only', 'Adenosine challenge', 'Beta-blocker therapy'], answer: 1, rationale: 'Mobitz II (infranodal block): high risk of progression to complete heart block, especially under anesthesia. Permanent pacemaker before elective surgery (or temporary pacing pads ready).' },
  { id: 270, section: 9, q: 'Severe hypothyroidism (myxedema coma) anesthetic implications include:', options: ['Increased MAC', 'Decreased MAC, hypothermia, bradycardia, hypotension, hyponatremia, slow drug metabolism, sensitive to anesthetics', 'Hyperthermia', 'Hyperventilation', 'Hypertension'], answer: 1, rationale: 'Severe hypothyroidism: ↓MAC, hypothermia, ↓CO, bradycardia, hyponatremia, hypoglycemia, slow metabolism, exquisite sensitivity to anesthetics, delayed gastric emptying. Defer elective surgery.' },
  { id: 271, section: 9, q: 'One-lung ventilation (OLV) physiology relies on:', options: ['Hypoxic pulmonary vasoconstriction (HPV) redirecting blood from non-ventilated to ventilated lung', 'Increased cardiac output to compensate', 'Passive blood flow patterns only', 'PEEP applied only to non-ventilated lung', 'Anaerobic metabolism in non-ventilated lung'], answer: 0, rationale: 'HPV: alveolar hypoxia → local pulmonary vasoconstriction → blood redirected to better-ventilated alveoli → IMPROVES V/Q. HPV inhibited by volatile anesthetics (>1 MAC). Optimize OLV: TV 4-6 mL/kg IBW, CPAP to non-ventilated.' },
  { id: 272, section: 9, q: 'Aortic cross-clamping at the supraceliac level causes which immediate hemodynamic change?', options: ['Severe decrease in afterload and hypotension', 'Marked increase in SVR/afterload, increase in proximal MAP, decrease in distal organ perfusion (kidneys, viscera, spinal cord)', 'Bradycardia', 'Decrease in preload', 'No change'], answer: 1, rationale: 'Aortic XC → ↑↑SVR (proximal HTN), ↑LV wall stress, ↓distal perfusion (renal, gut, cord), metabolic acidosis. At clamp release: distributive vasodilation → hypotension.' },
  { id: 273, section: 9, q: 'DIC (disseminated intravascular coagulation) management focuses primarily on:', options: ['Heparin in all cases', 'Treating the underlying cause (sepsis, trauma, obstetric, malignancy) + supportive blood products as bleeding/clinical condition dictate', 'FFP and platelets routinely', 'Antifibrinolytics universally', 'Avoid all transfusions'], answer: 1, rationale: 'DIC: address underlying trigger (sepsis, AFE, abruption, trauma, malignancy). Supportive: cryo (fibrinogen <100-150), FFP, platelets (<50 with bleeding). Heparin controversial — primarily for chronic compensated thrombotic DIC.' },
  { id: 274, section: 9, q: 'Acute respiratory distress syndrome (ARDS) ventilation strategy includes:', options: ['TV 12 mL/kg actual body weight, PEEP 0', 'TV 6 mL/kg IBW, plateau pressure ≤30, optimized PEEP, FiO₂ lowest tolerable, permissive hypercapnia, prone positioning for severe', 'Volume-control with TV 10 mL/kg', '100% O₂ always', 'Aggressive recruitment without PEEP'], answer: 1, rationale: 'ARDSnet: TV 6 mL/kg IBW, Pplat ≤30, PEEP per FiO₂ ladder, permissive hypercapnia (pH ≥7.2), driving pressure goal <14. Prone positioning for moderate-severe ARDS (P/F <150) → 16+ h/day.' },
  { id: 275, section: 9, q: 'Anesthetic agents safe in severe hepatic dysfunction include all EXCEPT:', options: ['Cisatracurium', 'Remifentanil', 'Sevoflurane and isoflurane at usual MAC', 'Propofol (modestly reduced dose)', 'Halothane (historic concern for hepatotoxicity)'], answer: 4, rationale: 'Halothane hepatitis (rare, immune-mediated) historically led to its decline. Modern volatiles (iso, des, sevo) less hepatotoxic. Cisatracurium (Hofmann elimination) and remifentanil (esterase) are ideal.' },
  { id: 276, section: 9, q: 'SGLT-2 inhibitors (empagliflozin, dapagliflozin) should be held preoperatively because of risk of:', options: ['Hypoglycemia', 'Euglycemic diabetic ketoacidosis (euDKA)', 'Hyperkalemia', 'Liver failure', 'Bradycardia'], answer: 1, rationale: 'SGLT-2 inhibitors: perioperative stress + fasting + ketogenic milieu → euDKA (normal/mildly elevated glucose but AGMA and ketosis). FDA: hold 3-4 days preop.' },
  { id: 277, section: 9, q: 'Aortic regurgitation anesthetic goals favor:', options: ['Fast HR (shortens diastole, reduces regurgitant volume), reduced afterload, maintained preload', 'Slow HR and high SVR', 'Profound bradycardia', 'Aggressive volume restriction', 'All vasodilators contraindicated'], answer: 0, rationale: 'Severe AR goals: "full, fast, forward." Higher HR (80-100) reduces diastolic time → less regurgitation. Avoid bradycardia. Maintain preload, reduce afterload (vasodilators improve forward flow).' },
  { id: 278, section: 9, q: 'Mitral regurgitation anesthetic goals favor:', options: ['High SVR, slow HR', 'Normal-to-high HR, low SVR (afterload reduction promotes forward flow), euvolemia, avoid pulmonary HTN', 'Bradycardia and high preload', 'Maximum SVR', 'Permissive hypoxia'], answer: 1, rationale: 'MR: "full, fast, vasodilated." Reduce afterload (less regurgitation, more forward flow). Maintain HR 80-100. Avoid factors raising PVR and sudden ↑SVR.' },
  { id: 279, section: 9, q: 'Heparin-induced thrombocytopenia (HIT) is best managed by:', options: ['Continuing heparin', 'Stopping all heparin, starting non-heparin anticoagulant (argatroban, bivalirudin, fondaparinux), avoiding warfarin until platelets recover', 'Platelet transfusion', 'FFP', 'Aspirin only'], answer: 1, rationale: 'HIT: STOP all heparin (including flushes, heparin-coated catheters). Bridge with argatroban or bivalirudin. Don\'t start warfarin until platelets >150 (warfarin-induced limb gangrene). LMWH cross-reacts — avoid.' },
  { id: 280, section: 9, q: 'von Willebrand disease type 1 (most common type) is best treated perioperatively with:', options: ['DDAVP (desmopressin) 0.3 mcg/kg IV — releases vWF from endothelium', 'Platelets only', 'FFP', 'Cryoprecipitate only', 'Antiplatelet agents'], answer: 0, rationale: 'vWD type 1 (quantitative deficiency): DDAVP 0.3 mcg/kg IV increases vWF/F-VIII 3-5x within 30 min. Test response preop. Tachyphylaxis after 2-3 doses. Type 2B contraindicated for DDAVP. Type 3 requires vWF concentrate.' },
  { id: 281, section: 9, q: 'Pacemaker code letter 1 designates:', options: ['Chamber paced (A, V, D)', 'Chamber sensed', 'Response to sensing', 'Rate modulation', 'Multisite pacing'], answer: 0, rationale: 'NBG pacing code: I — Chamber Paced (A, V, D = dual, O = none); II — Chamber Sensed; III — Response (I = inhibited, T = triggered, D = dual); IV — Rate modulation (R); V — Multisite.' },
  { id: 282, section: 9, q: 'Coronary anatomy: the LAD (left anterior descending) artery supplies:', options: ['Inferior wall', 'Anterior wall, anteroseptal LV, anterolateral papillary muscle, most of interventricular septum', 'Posterior wall only', 'RV free wall', 'Lateral wall via marginal branches'], answer: 1, rationale: 'LAD: anterior LV, anteroseptal, apex, anterior 2/3 of septum, anterolateral papillary. LCX: lateral wall. RCA: inferior LV, RV, AV node (90%), SA node (60%), posterior 1/3 of septum (right-dominant).' },
  { id: 283, section: 9, q: 'Status epilepticus during anesthesia is best treated initially with:', options: ['Lorazepam 0.1 mg/kg IV (or midazolam 0.2 mg/kg if no IV) — first line', 'Phenytoin first', 'Propofol 5 mg/kg only', 'Switch to ketamine', 'Wait and observe'], answer: 0, rationale: 'Status epilepticus: lorazepam 0.1 mg/kg IV first-line; if no IV — midazolam 10 mg IM. Second-line: fosphenytoin, levetiracetam, valproate. Refractory: propofol or pentobarbital infusion with EEG.' },
  { id: 284, section: 9, q: 'The principal causes of perioperative acute kidney injury include all EXCEPT:', options: ['Hypotension (MAP <60-65 sustained)', 'Nephrotoxic drugs (aminoglycosides, NSAIDs, contrast)', 'Sepsis', 'Rhabdomyolysis', 'Mild perioperative hypertension'], answer: 4, rationale: 'Perioperative AKI causes: prerenal (hypotension, hypovolemia, low CO), intrarenal (nephrotoxins, sepsis-ATN, rhabdo), postrenal. Mild HTN does NOT cause AKI.' },
  { id: 285, section: 9, q: 'A trauma patient with massive transfusion develops hypothermia, acidosis, and coagulopathy. This "lethal triad":', options: ['Is independent and reversible', 'Is mutually reinforcing — each worsens the others and increases mortality dramatically', 'Has no clinical significance', 'Affects only pediatric patients', 'Resolves spontaneously'], answer: 1, rationale: 'Trauma "lethal triad": hypothermia + acidosis + coagulopathy mutually reinforce → mortality cascade. Prevention: warm patient/fluids, buffer pH if extreme, balanced 1:1:1 resuscitation, TXA, damage-control surgery.' },
  { id: 286, section: 9, q: 'Cell salvage (intraoperative autologous transfusion) is contraindicated in which scenario?', options: ['Hip arthroplasty', 'Aortic aneurysm repair', 'Surgery in infected or malignant fields (relative — controversial, used with leukocyte-depletion filters in many centers)', 'Trauma', 'Spine surgery'], answer: 2, rationale: 'Cell salvage contraindications: traditionally infected field (sepsis risk) and malignancy (theoretical tumor seeding), although modern leukocyte-depletion filters allow use in many cancer cases.' },
  { id: 287, section: 9, q: 'Pituitary surgery anesthetic considerations include:', options: ['Awake fiberoptic preferred', 'Smooth induction, avoid coughing/bucking, plan for transsphenoidal positioning with eye protection, anticipate diabetes insipidus postop, hormonal coverage (stress steroids if pan-hypopituitarism)', 'Avoid all opioids', 'Mandatory awake craniotomy', 'TEE required'], answer: 1, rationale: 'Pituitary surgery: smooth induction, throat pack (count carefully), VAE risk (variable), postop diabetes insipidus (polyuria → DDAVP), hormone replacement, stress steroids if cortisol deficient.' },
  { id: 288, section: 9, q: 'VAE (venous air embolism) treatment includes all EXCEPT:', options: ['Flood surgical field with saline; pack venous source', 'Discontinue N₂O if in use', 'Left lateral decubitus, Trendelenburg (to keep air in right atrium)', 'Aspirate from CVP / multi-orifice catheter in RA', 'Mechanical hyperventilation to PaCO₂ <25'], answer: 4, rationale: 'VAE treatment: stop entrainment (flood field), 100% O₂, STOP N₂O (expands bubbles 34×), Durant position (left lateral + Trendelenburg), aspirate from CVC. Hyperventilation NOT routine.' },
  { id: 289, section: 9, q: 'Cryoprecipitate is the appropriate product for:', options: ['Volume expansion', 'Replacement of fibrinogen (<150 mg/dL with bleeding), Factor VIII, vWF, Factor XIII, fibronectin', 'RBC replacement', 'Reverse warfarin', 'Reverse heparin'], answer: 1, rationale: 'Cryoprecipitate: cold-precipitated from FFP. Rich in fibrinogen, factor VIII, vWF, factor XIII, fibronectin. Dose: 1 unit/10 kg raises fibrinogen ~50 mg/dL.' },
  { id: 290, section: 9, q: 'Kidney transplant anesthesia (recipient) typically uses:', options: ['Spinal anesthesia preferred', 'GA with avoidance of nephrotoxins, careful fluid management (often liberal hydration, mannitol for graft perfusion, mannitol/furosemide for diuresis at reperfusion), avoidance of pancuronium (renal clearance)', 'Local infiltration', 'Always TIVA', 'No anesthesia required'], answer: 1, rationale: 'Kidney transplant: GA most common. Liberal fluids (CVP 10-15) for graft perfusion. Mannitol 0.5 g/kg + furosemide 0.5 mg/kg at vascular clamp release. Cisatracurium preferred. Watch for reperfusion hyperkalemia.' },
  { id: 291, section: 9, q: 'TIPS (transjugular intrahepatic portosystemic shunt) procedure anesthesia considerations include:', options: ['Standard outpatient with no monitoring', 'Awareness of bleeding from varices, hepatic encephalopathy worsening, low cardiac reserve (cirrhotic cardiomyopathy), volume shifts at shunt creation', 'Routine epidural', 'Awake fiberoptic always', 'Trendelenburg only'], answer: 1, rationale: 'TIPS: usually MAC/sedation, sometimes GA. Cirrhosis concerns — coagulopathy, encephalopathy (avoid benzos), hyperdynamic state, hepatopulmonary syndrome. Shunt creation: portal pressure drops → hemodynamic shifts.' },
  { id: 292, section: 9, q: 'Postoperative pulmonary complications (PPCs) are reduced by:', options: ['Bed rest', 'Lung-protective ventilation, regional/multimodal analgesia for thoracic/abdominal incisions, early ambulation, incentive spirometry, smoking cessation, treating wheezing preop', 'Aggressive opioids only', 'Tight glycemic control alone', 'Routine prophylactic intubation postop'], answer: 1, rationale: 'PPC prevention: lung-protective ventilation (TV 6-8/PEEP 5/Pplat<16), opioid-sparing analgesia (regional, epidural), early ambulation, incentive spirometry, smoking cessation, CPAP for OSA.' },
  { id: 293, section: 9, q: 'EEG burst suppression during anesthesia is associated with:', options: ['Better postoperative outcomes always', 'Increased postoperative delirium and possibly mortality in elderly — minimize unnecessary burst suppression', 'Lower MAC', 'Improved hemodynamics', 'Required for general anesthesia'], answer: 1, rationale: 'Burst suppression: associated with postop delirium (elderly especially) and possibly mortality. Required only for specific neurosurgical cases (cerebral protection) and refractory status epilepticus. Use processed EEG to avoid.' },
  { id: 294, section: 9, q: 'Tricuspid regurgitation in an adult with pulmonary HTN is best managed by:', options: ['Same as left-sided MR', 'Maintain RV function: avoid factors raising PVR, support coronary perfusion of RV (systemic BP), gentle inotropic support (milrinone, dobutamine), iNO', 'Aggressive afterload reduction', 'Volume restriction', 'Beta-blockade only'], answer: 1, rationale: 'TR with PH: "protect the RV." Avoid PVR triggers. Maintain systemic BP for RV coronary supply. Inotropic support if RV failing — milrinone (PDE3, reduces PVR), dobutamine, iNO for selective pulmonary vasodilation.' },
  { id: 295, section: 9, q: 'Bronchopleural fistula anesthesia: best strategy for one-lung ventilation is:', options: ['Mask ventilation', 'Awake intubation with bronchial blocker or double-lumen tube to isolate fistula side; avoid positive-pressure ventilation across fistula', 'Single-lumen tube and high PEEP', 'Avoid all anesthesia', 'LMA'], answer: 1, rationale: 'BPF: positive pressure → air leak through fistula → tension pneumothorax. Awake fiberoptic intubation if possible. DLT or bronchial blocker isolates fistula side. Avoid high airway pressures.' },
  { id: 296, section: 9, q: 'Contrast-induced nephropathy (CIN) prevention strategies include:', options: ['Aggressive hydration (IV saline or isotonic bicarbonate around contrast administration); avoid nephrotoxins; minimize contrast volume; use iso-osmolar contrast', 'Furosemide diuresis', 'N-acetylcysteine (mixed evidence)', 'Dialysis prophylactically', 'Both A and (controversially) C'], answer: 4, rationale: 'CIN prevention: hydration is most effective. N-acetylcysteine — mixed evidence; many guidelines no longer recommend it. Avoid concurrent nephrotoxins, minimize contrast volume, low-osmolar or iso-osmolar contrast.' },
  { id: 297, section: 9, q: 'Acromegaly anesthetic implications include all EXCEPT:', options: ['Difficult airway (large tongue, mandible, soft tissues, narrowed glottis)', 'Cardiomyopathy and HTN', 'OSA', 'Glucose intolerance/diabetes', 'Decreased MAC'], answer: 4, rationale: 'Acromegaly: airway (macroglossia, prognathism, glottic stenosis), cardiomyopathy (LVH, diastolic dysfunction), HTN, OSA, DM, peripheral neuropathy. MAC is UNCHANGED — not decreased.' },
  { id: 298, section: 9, q: 'Tumor lysis syndrome in oncology patients undergoing surgery presents with:', options: ['Hyperkalemia, hyperphosphatemia, hyperuricemia, hypocalcemia, possible AKI', 'Hypokalemia and alkalosis', 'Hyperglycemia only', 'Hypernatremia and dehydration', 'Hypothyroidism'], answer: 0, rationale: 'TLS: rapid cell lysis → release of intracellular contents. Hyper-K, hyper-PO₄ (→ binds Ca → hypoCa), hyper-uricemia → AKI. Prevention: aggressive hydration, allopurinol or rasburicase.' },
  { id: 299, section: 9, q: 'Severe pulmonary hypertension in a patient for non-cardiac surgery — anesthetic considerations include:', options: ['Routine spinal anesthesia regardless of severity', 'Avoid factors increasing PVR (hypoxia, hypercarbia, acidosis, hypothermia, light anesthesia, N₂O), support RV function, careful fluid balance, available pulmonary vasodilators (NO, prostacyclin), TEE monitoring for major surgery', 'Aggressive vasodilation with nitroprusside as first-line', 'Liberal fluid bolus loading throughout the case', 'TIVA only — volatile anesthetics are absolutely contraindicated'], answer: 1, rationale: 'Severe pulmonary HTN: high perioperative mortality (up to 18%). Continue chronic pulm vasodilators. Avoid PVR triggers. TEE, careful fluid balance. Inhaled NO (20-40 ppm) or inhaled prostacyclin for refractory crisis.' },
  { id: 300, section: 9, q: 'The most common cause of perioperative acute kidney injury is:', options: ['Direct nephrotoxic drugs alone', 'Pre-renal hypoperfusion from hypovolemia, hypotension, and low cardiac output', 'Post-renal obstruction', 'Contrast-induced nephropathy', 'Rhabdomyolysis'], answer: 1, rationale: 'Perioperative AKI is largely pre-renal — hypovolemia, hypotension (MAP <65 for sustained periods), low CO. Prevent: MAP >65 (higher in CKD/HTN), maintain euvolemia (balanced crystalloid > NS), avoid nephrotoxins.' },
  { id: 301, section: 9, q: 'Postoperative pulmonary complications are most strongly reduced by which intraoperative strategy?', options: ['FiO₂ 1.0 throughout', 'Lung-protective ventilation (TV 6-8 mL/kg IBW, PEEP, low driving pressure) plus minimize aspiration, multimodal analgesia, early extubation when appropriate', 'High tidal volume to prevent atelectasis', 'Volume-controlled ventilation with no PEEP', 'Avoiding regional anesthesia'], answer: 1, rationale: 'PPC prevention bundle: lung-protective ventilation, aspiration prevention, opioid-sparing analgesia (regional > opioid), full NMB reversal (TOF ratio >0.9), incentive spirometry/early ambulation, smoking cessation.' },
];